        const VERSION = "V5.0 ERP";

        const IDBCache = {
            init: () => new Promise((resolve, reject) => {
                const req = indexedDB.open('ERPCacheDB', 1);
                req.onupgradeneeded = (e) => {
                    if (!e.target.result.objectStoreNames.contains('NetworkCache')) {
                        e.target.result.createObjectStore('NetworkCache');
                    }
                };
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            }),
            set: async (key, val) => {
                try {
                    const db = await IDBCache.init();
                    db.transaction('NetworkCache', 'readwrite').objectStore('NetworkCache').put(val, key);
                } catch(e) {}
            },
            get: async (key) => {
                try {
                    const db = await IDBCache.init();
                    return await new Promise((resolve) => {
                        const req = db.transaction('NetworkCache', 'readonly').objectStore('NetworkCache').get(key);
                        req.onsuccess = () => resolve(req.result);
                        req.onerror = () => resolve(null);
                    });
                } catch(e) { return null; }
            }
        };

        const globalParseDate = (dateVal) => {
            if (!dateVal) return null;
            if (dateVal instanceof Date) {
                return isNaN(dateVal.getTime()) ? null : dateVal;
            }

            if (typeof dateVal === 'number') {
                if (dateVal > 30000 && dateVal < 60000) {
                    return new Date(Math.round((dateVal - 25569) * 86400 * 1000));
                }
            }

            if (typeof dateVal === 'string') {
                const s = dateVal.trim();
                if (!s) return null;

                // Clean ISO string with T
                if (s.includes('T')) {
                    const cleanDate = s.split('T')[0];
                    const parts = cleanDate.split('-');
                    if (parts.length === 3 && parts[0].length === 4) {
                        return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
                    }
                }

                // YYYY-MM-DD or YYYY/MM/DD
                if (/^\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2}/.test(s)) {
                    const parts = s.split(/[\/\-]/);
                    return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
                }

                // DD/MM/YYYY or DD-MM-YYYY or DD/MM/YY or DD-MM-YY (Default Spanish/Colombia day-first format)
                if (/^\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}/.test(s)) {
                    const parts = s.split(/[\/\-]/);
                    const day = parseInt(parts[0], 10);
                    const month = parseInt(parts[1], 10) - 1;
                    let year = parseInt(parts[2], 10);
                    if (year < 100) year += 2000;
                    return new Date(year, month, day);
                }

                // DD-MMM-YYYY or DD/MMM/YYYY or DD MMM YYYY (e.g. 11-jul-2026, 11-JUL-2026, 11 jul 2026)
                const monthMap = {
                    ene: 0, feb: 1, mar: 2, abr: 3, may: 4, jun: 5,
                    jul: 6, ago: 7, sep: 8, oct: 9, nov: 10, dic: 11,
                    jan: 0, apr: 3, aug: 7, dec: 11
                };
                const textParts = s.toLowerCase().replace('.', '').split(/[\/\-\s]+/);
                if (textParts.length === 3) {
                    const day = parseInt(textParts[0], 10);
                    let year = parseInt(textParts[2], 10);
                    if (!isNaN(year) && year < 100) year += 2000;
                    const monthStr = textParts[1].substring(0, 3);
                    if (!isNaN(day) && !isNaN(year) && monthMap[monthStr] !== undefined) {
                        return new Date(year, monthMap[monthStr], day);
                    }
                }

                const dateObj = new Date(s);
                if (!isNaN(dateObj.getTime())) {
                    const offset = dateObj.getTimezoneOffset() * 60000;
                    return new Date(dateObj.getTime() + offset);
                }
            }

            return null;
        };

