                    entityName: 'ALÓ CREDIT COLOMBIA S.A.S.',
                    color: '#4F46E5',
                    headerBg: 'bg-indigo-600',
                    btnBg: 'bg-indigo-600 hover:bg-indigo-700',
                    btnActive: 'bg-indigo-600 text-white shadow-md scale-105',
                    badgeClass: 'text-indigo-600',
                    logoUrl: companyInfo.logoUrl,
                    calcComision: (recibe) => recibe * 0.55,
