/* MODULE 3: TABLERO VIEW */

const ConfigColumnasModal = ({ portfolio, onClose, db, showToast }) => {
    const [config, setConfig] = React.useState({});
    const [isSaving, setIsSaving] = React.useState(false);

    // Schema definition for each portfolio
    const schemas = {
        payjoy: [
            { key: 'ID_CREDITO', label: 'ID Crédito / Tag', default: 'ID CREDITO' },
            { key: 'CUOTAS_PAGADAS', label: 'Cuotas Pagadas', default: 'CUOTAS PAGADAS' },
            { key: 'VALOR_PAGADO', label: 'Valor Pagado', default: 'VALOR PAGADO' }
        ],
        alocredit: [
            { key: 'CEDULA', label: 'Cédula', default: 'CEDULA' },
            { key: 'NOMBRE', label: 'Nombre Cliente', default: 'NOMBRE' },
            { key: 'CELULAR', label: 'Celular', default: 'CELULAR' },
            { key: 'EQUIPO', label: 'Equipo / Referencia', default: 'EQUIPO' },
            { key: 'IMEI', label: 'IMEI', default: 'IMEI' },
            { key: 'FECHA_VENTA', label: 'Fecha Venta', default: 'FECHA' },
            { key: 'VALOR_VENTA', label: 'Valor Venta', default: 'VALOR VENTA' },
            { key: 'INICIAL', label: 'Cuota Inicial', default: 'INICIAL' },
            { key: 'SALDO', label: 'Saldo a Financiar', default: 'SALDO' },
            { key: 'PLAZO', label: 'Plazo (Meses/Semanas)', default: 'PLAZO' },
            { key: 'CUOTA', label: 'Valor Cuota', default: 'CUOTA' },
            { key: 'TIENDA', label: 'Tienda / Aliado', default: 'TIENDA' },
            { key: 'ESTADO', label: 'Estado del Crédito', default: 'ESTADO' },
            { key: 'DIAS_MORA', label: 'Días de Mora', default: 'DIAS MORA' },
            { key: 'SALDO_MORA', label: 'Saldo en Mora', default: 'SALDO MORA' }
        ],
        krediya: [
            { key: 'CEDULA', label: 'Cédula', default: 'CEDULA' },
            { key: 'NOMBRE', label: 'Nombre Cliente', default: 'NOMBRE' },
            { key: 'CELULAR', label: 'Celular', default: 'CELULAR' },
            { key: 'EQUIPO', label: 'Equipo / Referencia', default: 'EQUIPO' },
            { key: 'IMEI', label: 'IMEI', default: 'IMEI' },
            { key: 'FECHA_VENTA', label: 'Fecha Venta', default: 'FECHA' },
            { key: 'VALOR_VENTA', label: 'Valor Venta', default: 'VALOR VENTA' },
            { key: 'INICIAL', label: 'Cuota Inicial', default: 'INICIAL' },
            { key: 'SALDO', label: 'Saldo a Financiar', default: 'SALDO' },
            { key: 'PLAZO', label: 'Plazo', default: 'PLAZO' },
            { key: 'CUOTA', label: 'Valor Cuota', default: 'CUOTA' },
            { key: 'TIENDA', label: 'Tienda / Aliado', default: 'TIENDA' }
        ],
        credismart: [
            { key: 'CEDULA', label: 'Cédula', default: 'CEDULA' },
            { key: 'NOMBRE', label: 'Nombre Cliente', default: 'NOMBRE' },
            { key: 'ESTADO', label: 'Estado del Crédito', default: 'ESTADO' },
            { key: 'DIAS_MORA', label: 'Días de Mora', default: 'DIAS MORA' },
            { key: 'SALDO_MORA', label: 'Saldo en Mora', default: 'SALDO MORA' }
        ]
    };

    const schema = schemas[portfolio] || [];

    React.useEffect(() => {
        let loadedConfig = {};
        if (db && db.config_archivos_cartera) {
            const row = db.config_archivos_cartera.find(r => String(r.financiera).toUpperCase() === String(portfolio).toUpperCase());
            if (row && row.config_json) {
                try {
                    loadedConfig = JSON.parse(row.config_json);
                } catch (e) {}
            }
        }
        // Initialize with default or loaded
        const initConf = {};
        schema.forEach(field => {
            initConf[field.key] = loadedConfig[field.key] || field.default;
        });
        setConfig(initConf);
    }, [portfolio, db]);

    const handleSave = async () => {
        setIsSaving(true);
        try {
            const separator = SCRIPT_URL.includes('?') ? '&' : '?';
            const payload = {
                financiera: portfolio,
                config_json: config
            };
            const response = await fetch(`${SCRIPT_URL}${separator}action=guardarConfigArchivosCartera`, {
                method: 'POST',
                mode: 'cors',
                headers: { 'Content-Type': 'text/plain' },
                body: JSON.stringify({ action: 'guardarConfigArchivosCartera', data: payload })
            });
            const result = await response.json();
            if (result.status === 'success' || result.data?.status === 'success') {
                showToast("Configuración de columnas guardada.", "success");
                
                // Update local db state if possible, though it requires reload for full effect
                if (db.config_archivos_cartera) {
                    const row = db.config_archivos_cartera.find(r => String(r.financiera).toUpperCase() === String(portfolio).toUpperCase());
                    if (row) {
                        row.config_json = JSON.stringify(config);
                    } else {
                        db.config_archivos_cartera.push({ financiera: portfolio.toUpperCase(), config_json: JSON.stringify(config) });
                    }
                }
                
                onClose();
            } else {
                showToast("Error al guardar la configuración.", "error");
            }
        } catch (error) {
            console.error("Error saving config:", error);
            showToast("Error de conexión al guardar.", "error");
        }
        setIsSaving(false);
    };

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden flex flex-col border border-slate-200 max-h-[90vh]">
                <div className="p-5 border-b border-slate-100 bg-slate-50 flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-slate-200 text-slate-700 rounded-2xl shadow-sm">
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-6 h-6"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1-2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>
                        </div>
                        <div>
                            <h3 className="font-black text-slate-900 text-lg tracking-tight">Mapeo de Columnas</h3>
                            <p className="text-[10px] uppercase tracking-widest font-bold text-slate-400">FINANCIERA: {String(portfolio).toUpperCase()}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-full transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-5 h-5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                    </button>
                </div>
                <div className="p-6 overflow-y-auto custom-scrollbar flex-1 space-y-4">
                    <p className="text-xs text-slate-500 font-medium mb-2">Escribe el nombre exacto de la columna en el archivo Excel que descargas de <b>{String(portfolio).toUpperCase()}</b> para cada dato requerido.</p>
                    {schema.map(field => (
                        <div key={field.key} className="flex flex-col">
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 ml-1">{field.label}</label>
                            <input 
                                type="text"
                                value={config[field.key] || ''}
                                onChange={e => setConfig({...config, [field.key]: e.target.value})}
                                className="w-full bg-slate-50 border border-slate-200 py-2.5 px-4 rounded-xl text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all placeholder:text-slate-300 placeholder:font-normal"
                                placeholder={`Ej: ${field.default}`}
                            />
                        </div>
                    ))}
                </div>
                <div className="p-5 border-t border-slate-100 bg-slate-50 flex justify-end shrink-0 gap-3">
                    <button onClick={onClose} className="px-5 py-2.5 rounded-full font-bold text-sm text-slate-600 hover:bg-slate-200 transition-colors">
                        Cancelar
                    </button>
                    <button 
                        onClick={handleSave}
                        disabled={isSaving}
                        className="px-6 py-2.5 bg-indigo-600 text-white rounded-full font-bold text-sm shadow-md hover:bg-indigo-700 hover:shadow-lg hover:-translate-y-0.5 transition-all disabled:opacity-50 flex items-center gap-2"
                    >
                        {isSaving ? "Guardando..." : "Guardar Mapeo"}
                    </button>
                </div>
            </div>
        </div>
    );
};

