                    'FECHA DE PAGO': primeraCuotaStr,
                    'CEDULA': cedulaClean,
                    'CC': cedulaClean,
                    'DOCUMENTO': cedulaClean,
                    'NOMBRE CLIENTE': manualForm.nombre.trim().toUpperCase(),
                    'CLIENTE': manualForm.nombre.trim().toUpperCase(),
                    'NOMBRES': manualForm.nombre.trim().toUpperCase(),
                    'CELULAR': manualForm.celular.replace(/\D/g, ''),
                    'TELEFONO': manualForm.celular.replace(/\D/g, ''),
                    'EQUIPO': manualForm.equipo.trim().toUpperCase(),
                    'DESCRIPCION': manualForm.equipo.trim().toUpperCase(),
                    'DESCRIPCIÓN': manualForm.equipo.trim().toUpperCase(),
                    'REFERENCIA': manualForm.equipo.trim().toUpperCase(),
                    'MODELO': manualForm.equipo.trim().toUpperCase(),
