        const AgendaVisitasView = ({ db, currentUser, userPerms, apiCall, showToast, setActiveView }) => {
            const { useState, useEffect, useCallback, useMemo } = React;

            const [activeFilter, setActiveFilter] = useState('todas');
            const [searchTerm, setSearchTerm] = useState('');
            const [selectedTask, setSelectedTask] = useState(null);
            const [detailTab, setDetailTab] = useState('detalles');
            const [showNewTaskModal, setShowNewTaskModal] = useState(false);

            const [newTask, setNewTask] = useState({
                id_cliente: '',
                cliente_nombre: '',
                direccion: '',
                fecha_programada: new Date().toISOString().split('T')[0],
                hora_programada: '09:00',
                prioridad: 'Media',
                descripcion: '',
                checklist: [
                    { id: 1, text: 'Verificar exhibición y material POP de la tienda', completed: false },
                    { id: 2, text: 'Revisar inventario y disponibilidad de referencias', completed: false },
                    { id: 3, text: 'Reunión de alineación con encargado de tienda', completed: false },
                    { id: 4, text: 'Seguimiento a créditos pendientes y recaudo', completed: false },
                    { id: 5, text: 'Verificar estado de avisos y publicidad externa', completed: false }
                ]
            });

            const [geoLoc, setGeoLoc] = useState({ lat: null, lon: null, accuracy: null, loading: false, error: null });
            const [evidenceType, setEvidenceType] = useState('Fachada de Tienda');
            const [evidenceImg, setEvidenceImg] = useState('');
            const [evidenceNotes, setEvidenceNotes] = useState('');
            const [submittingEvidencia, setSubmittingEvidencia] = useState(false);

            const [checkinObs, setCheckinObs] = useState('');
            const [submittingAction, setSubmittingAction] = useState(false);

            const availableClientes = useMemo(() => {
                const list = db.clientes || [];
                if (userPerms?.isGlobalAdmin) return list;
                const myUN = String(userPerms?.un || '').trim().toLowerCase();
                if (!myUN) return list;
                return list.filter(c => {
                    const clientUN = String(c.un || c.UN || c.UnidaddeNegocio || c['UNIDAD DE NEGOCIO'] || '').trim().toLowerCase();
                    return clientUN === myUN;
                });
            }, [db.clientes, userPerms]);

            const myTasks = useMemo(() => {
                const allTareas = db.trop_tareas || [];
                const comercialName = String(currentUser?.nombre_cliente || currentUser?.nombre || '').trim().toLowerCase();
                const comercialId = String(currentUser?.id_cliente || currentUser?.id || '').trim().toLowerCase();

                return allTareas.filter(t => {
                    if (!userPerms?.isGlobalAdmin) {
                        const taskComercialName = String(t.COMERCIAL_NOMBRE || t.comercial_nombre || '').trim().toLowerCase();
                        const taskComercialId = String(t.COMERCIAL_ID || t.comercial_id || '').trim().toLowerCase();
                        if (comercialName && taskComercialName && !taskComercialName.includes(comercialName) && !comercialName.includes(taskComercialName) && taskComercialId !== comercialId) {
                            return false;
                        }
                    }

                    const estado = String(t.ESTADO || t.estado || 'Pendiente').toLowerCase();
                    const todayStr = new Date().toISOString().split('T')[0];
                    const fechaProg = String(t.FECHA_PROGRAMADA || t.fecha_programada || '');

                    if (activeFilter === 'hoy' && !fechaProg.includes(todayStr) && fechaProg !== todayStr) return false;
                    if (activeFilter === 'pendiente' && estado !== 'pendiente') return false;
                    if (activeFilter === 'proceso' && estado !== 'en proceso') return false;
                    if (activeFilter === 'completada' && estado !== 'completada') return false;

                    if (searchTerm.trim() !== '') {
                        const st = searchTerm.toLowerCase();
                        const cliente = String(t.CLIENTE_NOMBRE || t.cliente_nombre || '').toLowerCase();
                        const dir = String(t.DIRECCION || t.direccion || '').toLowerCase();
                        const desc = String(t.DESCRIPCION || t.descripcion || '').toLowerCase();
                        return cliente.includes(st) || dir.includes(st) || desc.includes(st);
                    }

                    return true;
                });
            }, [db.trop_tareas, currentUser, userPerms, activeFilter, searchTerm]);

            const captureGPS = useCallback(() => {
                if (!navigator.geolocation) {
                    setGeoLoc({ lat: null, lon: null, accuracy: null, loading: false, error: 'El navegador no soporta Geolocalización.' });
                    showToast('Geolocalización no soportada en este navegador.', 'error');
                    return;
                }
                setGeoLoc(prev => ({ ...prev, loading: true, error: null }));
                navigator.geolocation.getCurrentPosition(
                    (pos) => {
                        setGeoLoc({
                            lat: pos.coords.latitude.toFixed(6),
                            lon: pos.coords.longitude.toFixed(6),
                            accuracy: pos.coords.accuracy ? pos.coords.accuracy.toFixed(1) : '10.0',
                            loading: false,
                            error: null
                        });
                    },
                    (err) => {
                        let errMsg = 'No se pudo obtener la ubicación GPS.';
                        if (err.code === err.PERMISSION_DENIED) errMsg = 'Permiso de GPS denegado por el usuario.';
                        else if (err.code === err.POSITION_UNAVAILABLE) errMsg = 'Ubicación GPS no disponible.';
                        else if (err.code === err.TIMEOUT) errMsg = 'Tiempo de espera agotado al consultar GPS.';
                        setGeoLoc({ lat: null, lon: null, accuracy: null, loading: false, error: errMsg });
                        showToast(errMsg, 'error');
                    },
                    { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
                );
            }, [showToast]);

            useEffect(() => {
                if (selectedTask && (detailTab === 'evidencia' || detailTab === 'monitoreo')) {
                    captureGPS();
                }
            }, [detailTab, selectedTask, captureGPS]);

            const handleSelectClienteInNewTask = (clientId) => {
                const cli = availableClientes.find(c => String(c.id_cliente || c.ID_CLIENTE).trim() === String(clientId).trim());
                if (cli) {
                    setNewTask(prev => ({
                        ...prev,
                        id_cliente: cli.id_cliente || cli.ID_CLIENTE || '',
                        cliente_nombre: cli.nombre_cliente || cli.NOMBRE_CLIENTE || '',
                        direccion: cli.direccion || cli.DIRECCION || cli.tienda || ''
                    }));
                } else {
                    setNewTask(prev => ({ ...prev, id_cliente: clientId, cliente_nombre: '', direccion: '' }));
                }
            };

            const handleCreateTask = async (e) => {
                e.preventDefault();
                if (!newTask.id_cliente || !newTask.fecha_programada) {
                    showToast('Selecciona un cliente y la fecha programada.', 'error');
                    return;
                }

                const payload = {
                    comercial_id: currentUser?.id_cliente || currentUser?.id || 'CIA-001',
                    comercial_nombre: currentUser?.nombre_cliente || currentUser?.nombre || 'Comercial CIA',
                    id_cliente: newTask.id_cliente,
                    cliente_nombre: newTask.cliente_nombre,
                    direccion: newTask.direccion,
                    fecha_programada: newTask.fecha_programada,
                    hora_programada: newTask.hora_programada,
                    prioridad: newTask.prioridad,
                    estado: 'Pendiente',
                    descripcion: newTask.descripcion,
                    checklist_json: newTask.checklist
                };

                await apiCall('guardarTareaTrop', payload, 'Tarea de visita asignada correctamente.');
                setShowNewTaskModal(false);
                setNewTask({
                    id_cliente: '',
                    cliente_nombre: '',
                    direccion: '',
                    fecha_programada: new Date().toISOString().split('T')[0],
                    hora_programada: '09:00',
                    prioridad: 'Media',
                    descripcion: '',
                    checklist: [
                        { id: 1, text: 'Verificar exhibición y material POP de la tienda', completed: false },
                        { id: 2, text: 'Revisar inventario y disponibilidad de referencias', completed: false },
                        { id: 3, text: 'Reunión de alineación con encargado de tienda', completed: false },
                        { id: 4, text: 'Seguimiento a créditos pendientes y recaudo', completed: false },
                        { id: 5, text: 'Verificar estado de avisos y publicidad externa', completed: false }
                    ]
                });
            };

            const handleImageUpload = (e) => {
                const file = e.target.files[0];
                if (!file) return;

                if (file.size > 5 * 1024 * 1024) {
                    showToast('La imagen supera los 5MB. Elige una más liviana.', 'error');
                    return;
                }

                const reader = new FileReader();
                reader.onloadend = () => {
                    setEvidenceImg(reader.result);
                };
                reader.readAsDataURL(file);
            };

            const handleSaveEvidencia = async () => {
                if (!geoLoc.lat || !geoLoc.lon) {
                    showToast('Se requiere ubicación GPS para adjuntar evidencia. Haz clic en "Actualizar Coordenadas".', 'error');
                    return;
                }
                if (!evidenceImg) {
                    showToast('Selecciona o toma una fotografía como evidencia.', 'error');
                    return;
                }

                setSubmittingEvidencia(true);
                try {
                    const activeVisit = (db.trop_visitas || []).find(v => String(v.ID_TAREA || v.id_tarea).trim() === String(selectedTask.ID_TAREA || selectedTask.id_tarea).trim());
                    const payload = {
                        id_visita: activeVisit ? (activeVisit.ID_VISITA || activeVisit.id_visita) : '',
                        id_tarea: selectedTask.ID_TAREA || selectedTask.id_tarea,
                        comercial_id: currentUser?.id_cliente || currentUser?.id || 'CIA-001',
                        comercial_nombre: currentUser?.nombre_cliente || currentUser?.nombre || 'Comercial CIA',
                        id_cliente: selectedTask.ID_CLIENTE || selectedTask.id_cliente,
                        cliente_nombre: selectedTask.CLIENTE_NOMBRE || selectedTask.cliente_nombre,
                        latitud: geoLoc.lat,
                        longitud: geoLoc.lon,
                        accuracy: geoLoc.accuracy,
                        tipo_evidencia: evidenceType,
                        imagen_base64_o_url: evidenceImg,
                        notas: evidenceNotes
                    };

                    await apiCall('guardarEvidenciaTrop', payload, 'Evidencia con GPS registrada correctamente.');
                    setEvidenceImg('');
                    setEvidenceNotes('');
                } catch (err) {
                    showToast(err.message || 'Error al guardar la evidencia.', 'error');
                } finally {
                    setSubmittingEvidencia(false);
                }
            };

            const handleCheckIn = async () => {
                if (!geoLoc.lat || !geoLoc.lon) {
                    showToast('Obligatorio obtener GPS antes de Check-in.', 'error');
                    return;
                }

                setSubmittingAction(true);
                try {
                    const taskId = selectedTask.ID_TAREA || selectedTask.id_tarea;
                    const payload = {
                        id_tarea: taskId,
                        comercial_id: currentUser?.id_cliente || currentUser?.id || 'CIA-001',
                        comercial_nombre: currentUser?.nombre_cliente || currentUser?.nombre || 'Comercial CIA',
                        id_cliente: selectedTask.ID_CLIENTE || selectedTask.id_cliente,
                        cliente_nombre: selectedTask.CLIENTE_NOMBRE || selectedTask.cliente_nombre,
                        latitud: geoLoc.lat,
                        longitud: geoLoc.lon,
                        accuracy: geoLoc.accuracy,
                        fecha_programada: selectedTask.FECHA_PROGRAMADA || selectedTask.fecha_programada,
                        hora_programada: selectedTask.HORA_PROGRAMADA || selectedTask.hora_programada,
                        observaciones: checkinObs || 'Check-in realizado por comercial CIA'
                    };

                    await apiCall('registrarCheckInTrop', payload, 'Check-in registrado. Visita en proceso.');
                    setCheckinObs('');
                } catch (err) {
                    showToast(err.message || 'Error al realizar Check-in.', 'error');
                } finally {
                    setSubmittingAction(false);
                }
            };

            const handleCheckOut = async () => {
                if (!geoLoc.lat || !geoLoc.lon) {
                    showToast('Obligatorio obtener GPS antes de Check-out.', 'error');
                    return;
                }

                setSubmittingAction(true);
                try {
                    const taskId = selectedTask.ID_TAREA || selectedTask.id_tarea;
                    const activeVisit = (db.trop_visitas || []).find(v => String(v.ID_TAREA || v.id_tarea).trim() === String(taskId).trim() && String(v.ESTADO_VISITA || v.estado_visita) === 'En Proceso');

                    const payload = {
                        id_visita: activeVisit ? (activeVisit.ID_VISITA || activeVisit.id_visita) : '',
                        id_tarea: taskId,
                        latitud: geoLoc.lat,
                        longitud: geoLoc.lon,
                        accuracy: geoLoc.accuracy,
                        observaciones: checkinObs || 'Check-out realizado. Visita finalizada.'
                    };

                    await apiCall('registrarCheckOutTrop', payload, 'Check-out completado exitosamente.');
                    setCheckinObs('');
                } catch (err) {
                    showToast(err.message || 'Error al realizar Check-out.', 'error');
                } finally {
                    setSubmittingAction(false);
                }
            };

            const handleToggleChecklistItem = async (itemIndex) => {
                if (!selectedTask) return;
                let currentChecklist = [];
                try {
                    const rawCl = selectedTask.CHECKLIST_JSON || selectedTask.checklist_json || '[]';
                    currentChecklist = typeof rawCl === 'string' ? JSON.parse(rawCl) : rawCl;
                } catch (e) {
                    currentChecklist = [];
                }

                const updatedChecklist = currentChecklist.map((it, idx) => idx === itemIndex ? { ...it, completed: !it.completed } : it);

                const updatedTask = { ...selectedTask, CHECKLIST_JSON: updatedChecklist, checklist_json: updatedChecklist };
                setSelectedTask(updatedTask);

                const payload = {
                    id_tarea: selectedTask.ID_TAREA || selectedTask.id_tarea,
                    checklist_json: updatedChecklist
                };
                await apiCall('guardarTareaTrop', payload, 'Checklist actualizado.');
            };

            const [newChecklistText, setNewChecklistText] = useState('');
            const handleAddChecklistItem = async () => {
                if (!newChecklistText.trim() || !selectedTask) return;
                let currentChecklist = [];
                try {
                    const rawCl = selectedTask.CHECKLIST_JSON || selectedTask.checklist_json || '[]';
                    currentChecklist = typeof rawCl === 'string' ? JSON.parse(rawCl) : rawCl;
                } catch (e) { currentChecklist = []; }

                const newItem = { id: Date.now(), text: newChecklistText.trim(), completed: false };
                const updatedChecklist = [...currentChecklist, newItem];

                setSelectedTask({ ...selectedTask, CHECKLIST_JSON: updatedChecklist, checklist_json: updatedChecklist });
                setNewChecklistText('');

                const payload = {
                    id_tarea: selectedTask.ID_TAREA || selectedTask.id_tarea,
                    checklist_json: updatedChecklist
                };
                await apiCall('guardarTareaTrop', payload, 'Ítem agregado al checklist.');
            };

            const getTaskChecklist = (task) => {
                if (!task) return [];
                try {
                    const raw = task.CHECKLIST_JSON || task.checklist_json || '[]';
                    return typeof raw === 'string' ? JSON.parse(raw) : raw;
                } catch (e) {
                    return [];
                }
            };

            const metrics = useMemo(() => {
                const total = myTasks.length;
                const pendientes = myTasks.filter(t => String(t.ESTADO || t.estado).toLowerCase() === 'pendiente').length;
                const enProceso = myTasks.filter(t => String(t.ESTADO || t.estado).toLowerCase() === 'en proceso').length;
                const completadas = myTasks.filter(t => String(t.ESTADO || t.estado).toLowerCase() === 'completada').length;
                return { total, pendientes, enProceso, completadas };
            }, [myTasks]);

            const activeVisitForSelected = useMemo(() => {
                if (!selectedTask) return null;
                const taskId = selectedTask.ID_TAREA || selectedTask.id_tarea;
                return (db.trop_visitas || []).find(v => String(v.ID_TAREA || v.id_tarea).trim() === String(taskId).trim());
            }, [db.trop_visitas, selectedTask]);

            const evidencesForSelected = useMemo(() => {
                if (!selectedTask) return [];
                const taskId = selectedTask.ID_TAREA || selectedTask.id_tarea;
                return (db.trop_fotos_gps || []).filter(ev => String(ev.ID_TAREA || ev.id_tarea).trim() === String(taskId).trim());
            }, [db.trop_fotos_gps, selectedTask]);

            return (
                <div className="max-w-7xl mx-auto space-y-6 pb-12 animate-in fade-in duration-300">
                    <div className="bg-gradient-to-r from-[#2C4C8C] via-indigo-900 to-slate-900 rounded-3xl p-6 md:p-8 text-white shadow-xl relative overflow-hidden">
                        <div className="absolute right-0 top-0 bottom-0 opacity-10 pointer-events-none flex items-center pr-8">
                            <Icon name="Calendar" size={240} />
                        </div>
                        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 text-white/90 text-xs font-bold backdrop-blur-md mb-3 border border-white/20">
                                    <Icon name="MapPin" size={14} className="text-emerald-400" />
                                    <span>Módulo de Operación y Visitas CIA</span>
                                </div>
                                <h1 className="text-2xl md:text-3xl font-black tracking-tight">Agenda y Gestión de Visitas</h1>
                                <p className="text-indigo-200 text-sm mt-1 max-w-xl">
                                    Bienvenido, <strong className="text-white">{currentUser?.nombre_cliente || currentUser?.nombre || 'Comercial CIA'}</strong>. Organiza tus visitas a aliados comerciales, registra listas de verificación, evidencias fotográficas con GPS obligatorio y control de tiempos.
                                </p>
                            </div>
                            <div className="flex flex-wrap items-center gap-3 shrink-0">
                                <button
                                    onClick={() => setShowNewTaskModal(true)}
                                    className="px-5 py-3 bg-emerald-500 hover:bg-emerald-600 text-white font-black text-xs uppercase tracking-wider rounded-2xl shadow-lg hover:shadow-emerald-500/30 transition-all flex items-center gap-2 cursor-pointer"
                                >
                                    <Icon name="Plus" size={18} /> Nueva Tarea / Visita
                                </button>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6 pt-6 border-t border-white/10">
                            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10">
                                <span className="text-xs font-bold text-indigo-200 block uppercase">Total Programadas</span>
                                <span className="text-2xl font-black text-white mt-1 block">{metrics.total}</span>
                            </div>
                            <div className="bg-amber-500/20 backdrop-blur-md rounded-2xl p-4 border border-amber-400/30">
                                <span className="text-xs font-bold text-amber-200 block uppercase">Pendientes</span>
                                <span className="text-2xl font-black text-amber-300 mt-1 block">{metrics.pendientes}</span>
                            </div>
                            <div className="bg-blue-500/20 backdrop-blur-md rounded-2xl p-4 border border-blue-400/30">
                                <span className="text-xs font-bold text-blue-200 block uppercase">En Proceso</span>
                                <span className="text-2xl font-black text-blue-300 mt-1 block">{metrics.enProceso}</span>
                            </div>
                            <div className="bg-emerald-500/20 backdrop-blur-md rounded-2xl p-4 border border-emerald-400/30">
                                <span className="text-xs font-bold text-emerald-200 block uppercase">Completadas</span>
                                <span className="text-2xl font-black text-emerald-300 mt-1 block">{metrics.completadas}</span>
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-2xl p-4 border border-slate-200/80 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4">
                        <div className="flex items-center gap-2 overflow-x-auto custom-scrollbar w-full md:w-auto pb-1 md:pb-0">
                            <button
                                onClick={() => setActiveFilter('todas')}
                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap cursor-pointer ${activeFilter === 'todas' ? 'bg-[#2C4C8C] text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                Todas ({db.trop_tareas?.length || 0})
                            </button>
                            <button
                                onClick={() => setActiveFilter('hoy')}
                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap cursor-pointer ${activeFilter === 'hoy' ? 'bg-[#2C4C8C] text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                <Icon name="Calendar" size={14} className="inline mr-1" /> Hoy
                            </button>
                            <button
                                onClick={() => setActiveFilter('pendiente')}
                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap cursor-pointer ${activeFilter === 'pendiente' ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                Pendientes ({metrics.pendientes})
                            </button>
                            <button
                                onClick={() => setActiveFilter('proceso')}
                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap cursor-pointer ${activeFilter === 'proceso' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                En Proceso ({metrics.enProceso})
                            </button>
                            <button
                                onClick={() => setActiveFilter('completada')}
                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap cursor-pointer ${activeFilter === 'completada' ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                Completadas ({metrics.completadas})
                            </button>
                        </div>

                        <div className="relative w-full md:w-72">
                            <Icon name="Search" size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input
                                type="text"
                                placeholder="Buscar cliente o dirección..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500"
                            />
                        </div>
                    </div>

                    {myTasks.length === 0 ? (
                        <div className="bg-white rounded-3xl p-12 text-center border border-slate-200 shadow-sm space-y-4">
                            <div className="w-16 h-16 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center mx-auto">
                                <Icon name="Calendar" size={32} />
                            </div>
                            <h3 className="text-lg font-black text-slate-800">No se encontraron tareas o visitas programadas</h3>
                            <p className="text-slate-500 text-sm max-w-md mx-auto">
                                {searchTerm ? 'Prueba ajustando el término de búsqueda.' : 'Puedes agregar una nueva tarea de visita haciendo clic en el botón "Nueva Tarea / Visita".'}
                            </p>
                            <button
                                onClick={() => setShowNewTaskModal(true)}
                                className="px-5 py-2.5 bg-[#2C4C8C] text-white font-bold text-xs uppercase rounded-xl hover:bg-indigo-900 transition-colors inline-flex items-center gap-2 cursor-pointer"
                            >
                                <Icon name="Plus" size={16} /> Crear Tarea
                            </button>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {myTasks.map((t, idx) => {
                                const estado = String(t.ESTADO || t.estado || 'Pendiente').toLowerCase();
                                const prioridad = String(t.PRIORIDAD || t.prioridad || 'Media');
                                const checklist = getTaskChecklist(t);
                                const completedCount = checklist.filter(c => c.completed).length;
                                const progressPct = checklist.length > 0 ? Math.round((completedCount / checklist.length) * 100) : 0;

                                let statusBg = 'bg-amber-100 text-amber-800 border-amber-200';
                                if (estado === 'en proceso') statusBg = 'bg-blue-100 text-blue-800 border-blue-200';
                                else if (estado === 'completada') statusBg = 'bg-emerald-100 text-emerald-800 border-emerald-200';

                                let prioBg = 'bg-slate-100 text-slate-700';
                                if (prioridad.toLowerCase() === 'alta') prioBg = 'bg-rose-100 text-rose-700 font-black';
                                else if (prioridad.toLowerCase() === 'media') prioBg = 'bg-amber-100 text-amber-700 font-bold';

                                return (
                                    <div
                                        key={t.ID_TAREA || t.id_tarea || idx}
                                        className="bg-white rounded-3xl p-6 border border-slate-200/80 shadow-sm hover:shadow-xl transition-all duration-200 flex flex-col justify-between space-y-4 relative group"
                                    >
                                        <div className="space-y-3">
                                            <div className="flex items-center justify-between gap-2">
                                                <span className={`px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider border ${statusBg}`}>
                                                    {t.ESTADO || t.estado || 'Pendiente'}
                                                </span>
                                                <span className={`px-2.5 py-0.5 rounded-full text-[10px] uppercase tracking-wider ${prioBg}`}>
                                                    Prioridad {prioridad}
                                                </span>
                                            </div>

                                            <div>
                                                <h3 className="text-base font-black text-slate-900 group-hover:text-[#2C4C8C] transition-colors leading-snug">
                                                    {t.CLIENTE_NOMBRE || t.cliente_nombre || 'Aliado Comercial'}
                                                </h3>
                                                <p className="text-xs text-slate-500 mt-1 flex items-start gap-1">
                                                    <Icon name="MapPin" size={14} className="shrink-0 text-slate-400 mt-0.5" />
                                                    <span>{t.DIRECCION || t.direccion || 'Dirección no especificada'}</span>
                                                </p>
                                            </div>

                                            <div className="flex items-center gap-4 text-xs font-medium text-slate-600 bg-slate-50 p-3 rounded-2xl border border-slate-100">
                                                <div className="flex items-center gap-1.5">
                                                    <Icon name="Calendar" size={14} className="text-indigo-600" />
                                                    <span>{t.FECHA_PROGRAMADA || t.fecha_programada}</span>
                                                </div>
                                                <div className="flex items-center gap-1.5">
                                                    <Icon name="Clock" size={14} className="text-indigo-600" />
                                                    <span>{t.HORA_PROGRAMADA || t.hora_programada || '09:00'}</span>
                                                </div>
                                            </div>

                                            {t.DESCRIPCION || t.descripcion ? (
                                                <p className="text-xs text-slate-600 line-clamp-2 italic bg-amber-50/50 p-2.5 rounded-xl border border-amber-100">
                                                    "{t.DESCRIPCION || t.descripcion}"
                                                </p>
                                            ) : null}

                                            {checklist.length > 0 && (
                                                <div className="space-y-1.5 pt-1">
                                                    <div className="flex justify-between text-[11px] font-bold text-slate-500">
                                                        <span>Checklist ({completedCount}/{checklist.length})</span>
                                                        <span>{progressPct}%</span>
                                                    </div>
                                                    <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                                                        <div className="h-full bg-indigo-600 transition-all" style={{ width: `${progressPct}%` }}></div>
                                                    </div>
                                                </div>
                                            )}
                                        </div>

                                        <div className="pt-3 border-t border-slate-100 flex items-center justify-between">
                                            <span className="text-[10px] font-mono text-slate-400">{t.ID_TAREA || t.id_tarea}</span>
                                            <button
                                                onClick={() => {
                                                    setSelectedTask(t);
                                                    setDetailTab('detalles');
                                                }}
                                                className="px-4 py-2 bg-slate-900 hover:bg-[#2C4C8C] text-white font-bold text-xs rounded-xl transition-all flex items-center gap-1.5 shadow-sm cursor-pointer"
                                            >
                                                <span>Gestionar Visita</span>
                                                <Icon name="ChevronRight" size={14} />
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}

                    {showNewTaskModal && (
                        <div className="fixed inset-0 z-[7000] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in">
                            <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-6 md:p-8 space-y-6 max-h-[90vh] overflow-y-auto custom-scrollbar border border-slate-200">
                                <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2.5 bg-indigo-50 text-indigo-600 rounded-2xl">
                                            <Icon name="Calendar" size={24} />
                                        </div>
                                        <div>
                                            <h3 className="text-lg font-black text-slate-900">Programar Nueva Tarea / Visita</h3>
                                            <p className="text-xs text-slate-500">Asigna cliente, prioridad e ítems de verificación.</p>
                                        </div>
                                    </div>
                                    <button onClick={() => setShowNewTaskModal(false)} className="text-slate-400 hover:text-slate-600 p-2 rounded-full hover:bg-slate-100">
                                        <Icon name="X" size={20} />
                                    </button>
                                </div>

                                <form onSubmit={handleCreateTask} className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Cliente / Aliado Comercial *</label>
                                        <select
                                            required
                                            value={newTask.id_cliente}
                                            onChange={e => handleSelectClienteInNewTask(e.target.value)}
                                            className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                        >
                                            <option value="">-- Selecciona Aliado Comercial --</option>
                                            {availableClientes.map((c, i) => (
                                                <option key={`${c.id_cliente || c.ID_CLIENTE}-${i}`} value={c.id_cliente || c.ID_CLIENTE}>
                                                    {c.nombre_cliente || c.NOMBRE_CLIENTE} ({c.un || c.UN || 'UN'})
                                                </option>
                                            ))}
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Dirección de la Tienda *</label>
                                        <input
                                            type="text"
                                            required
                                            value={newTask.direccion}
                                            onChange={e => setNewTask({ ...newTask, direccion: e.target.value })}
                                            placeholder="Dirección o punto de encuentro"
                                            className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                        />
                                    </div>

                                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                        <div>
                                            <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Fecha Programada *</label>
                                            <input
                                                type="date"
                                                required
                                                value={newTask.fecha_programada}
                                                onChange={e => setNewTask({ ...newTask, fecha_programada: e.target.value })}
                                                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Hora Estimada</label>
                                            <input
                                                type="time"
                                                value={newTask.hora_programada}
                                                onChange={e => setNewTask({ ...newTask, hora_programada: e.target.value })}
                                                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Prioridad</label>
                                            <select
                                                value={newTask.prioridad}
                                                onChange={e => setNewTask({ ...newTask, prioridad: e.target.value })}
                                                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                            >
                                                <option value="Alta">Alta</option>
                                                <option value="Media">Media</option>
                                                <option value="Baja">Baja</option>
                                            </select>
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Descripción / Objetivo de la Visita</label>
                                        <textarea
                                            rows="2"
                                            value={newTask.descripcion}
                                            onChange={e => setNewTask({ ...newTask, descripcion: e.target.value })}
                                            placeholder="Detalla los objetivos principales de la gestión comercial..."
                                            className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                        />
                                    </div>

                                    <div className="pt-2 flex justify-end gap-3">
                                        <button
                                            type="button"
                                            onClick={() => setShowNewTaskModal(false)}
                                            className="px-5 py-2.5 text-slate-600 font-bold text-xs uppercase hover:bg-slate-100 rounded-xl transition-colors cursor-pointer"
                                        >
                                            Cancelar
                                        </button>
                                        <button
                                            type="submit"
                                            className="px-6 py-2.5 bg-[#2C4C8C] hover:bg-indigo-900 text-white font-black text-xs uppercase tracking-wider rounded-xl transition-all shadow-md cursor-pointer"
                                        >
                                            Guardar y Asignar Tarea
                                        </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    )}

                    {selectedTask && (
                        <div className="fixed inset-0 z-[7000] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in">
                            <div className="bg-white rounded-3xl shadow-2xl max-w-3xl w-full max-h-[92vh] flex flex-col overflow-hidden border border-slate-200">
                                <div className="bg-slate-900 p-6 text-white shrink-0 flex justify-between items-start">
                                    <div>
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-indigo-500/30 text-indigo-200 border border-indigo-400/30">
                                                {selectedTask.ID_TAREA || selectedTask.id_tarea}
                                            </span>
                                            <span className="text-xs text-slate-400 font-medium">
                                                {selectedTask.FECHA_PROGRAMADA || selectedTask.fecha_programada} @ {selectedTask.HORA_PROGRAMADA || selectedTask.hora_programada || '09:00'}
                                            </span>
                                        </div>
                                        <h2 className="text-xl font-black tracking-tight text-white">
                                            {selectedTask.CLIENTE_NOMBRE || selectedTask.cliente_nombre || 'Aliado Comercial'}
                                        </h2>
                                        <p className="text-xs text-slate-300 mt-1 flex items-center gap-1">
                                            <Icon name="MapPin" size={14} className="text-emerald-400" />
                                            <span>{selectedTask.DIRECCION || selectedTask.direccion}</span>
                                        </p>
                                    </div>
                                    <button
                                        onClick={() => setSelectedTask(null)}
                                        className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors cursor-pointer"
                                    >
                                        <Icon name="X" size={20} />
                                    </button>
                                </div>

                                <div className="bg-slate-100 border-b border-slate-200 px-6 pt-3 flex gap-2 overflow-x-auto shrink-0">
                                    <button
                                        onClick={() => setDetailTab('detalles')}
                                        className={`px-4 py-2.5 rounded-t-2xl font-black text-xs uppercase tracking-wider transition-all border-t border-x cursor-pointer ${detailTab === 'detalles' ? 'bg-white text-[#2C4C8C] border-slate-200 border-b-transparent shadow-sm' : 'text-slate-500 hover:text-slate-800 border-transparent'}`}
                                    >
                                        <Icon name="FileText" size={14} className="inline mr-1.5" /> Detalles
                                    </button>
                                    <button
                                        onClick={() => setDetailTab('checklist')}
                                        className={`px-4 py-2.5 rounded-t-2xl font-black text-xs uppercase tracking-wider transition-all border-t border-x cursor-pointer ${detailTab === 'checklist' ? 'bg-white text-[#2C4C8C] border-slate-200 border-b-transparent shadow-sm' : 'text-slate-500 hover:text-slate-800 border-transparent'}`}
                                    >
                                        <Icon name="CheckSquare" size={14} className="inline mr-1.5" /> Checklist
                                    </button>
                                    <button
                                        onClick={() => setDetailTab('evidencia')}
                                        className={`px-4 py-2.5 rounded-t-2xl font-black text-xs uppercase tracking-wider transition-all border-t border-x cursor-pointer ${detailTab === 'evidencia' ? 'bg-white text-[#2C4C8C] border-slate-200 border-b-transparent shadow-sm' : 'text-slate-500 hover:text-slate-800 border-transparent'}`}
                                    >
                                        <Icon name="Camera" size={14} className="inline mr-1.5" /> Evidencia (GPS)
                                    </button>
                                    <button
                                        onClick={() => setDetailTab('monitoreo')}
                                        className={`px-4 py-2.5 rounded-t-2xl font-black text-xs uppercase tracking-wider transition-all border-t border-x cursor-pointer ${detailTab === 'monitoreo' ? 'bg-white text-[#2C4C8C] border-slate-200 border-b-transparent shadow-sm' : 'text-slate-500 hover:text-slate-800 border-transparent'}`}
                                    >
                                        <Icon name="Clock" size={14} className="inline mr-1.5" /> Monitoreo (Check-in/out)
                                    </button>
                                </div>

                                <div className="p-6 overflow-y-auto custom-scrollbar flex-1 space-y-6">
                                    {detailTab === 'detalles' && (
                                        <div className="space-y-6 animate-in fade-in">
                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Estado de la Tarea</span>
                                                    <span className="text-sm font-black text-slate-800 uppercase">{selectedTask.ESTADO || selectedTask.estado || 'Pendiente'}</span>
                                                </div>
                                                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Prioridad</span>
                                                    <span className="text-sm font-black text-slate-800 uppercase">{selectedTask.PRIORIDAD || selectedTask.prioridad || 'Media'}</span>
                                                </div>
                                            </div>

                                            <div className="bg-indigo-50/60 p-5 rounded-2xl border border-indigo-100 space-y-3">
                                                <h4 className="text-xs font-black text-indigo-900 uppercase tracking-wider flex items-center gap-2">
                                                    <Icon name="Navigation" size={16} /> Ubicación y Dirección
                                                </h4>
                                                <p className="text-sm text-indigo-950 font-bold">{selectedTask.DIRECCION || selectedTask.direccion}</p>
                                                <a
                                                    href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(selectedTask.DIRECCION || selectedTask.direccion || selectedTask.CLIENTE_NOMBRE)}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-black tracking-wider transition-colors shadow-sm"
                                                >
                                                    <Icon name="Navigation" size={14} /> Abrir Navegación en Google Maps
                                                </a>
                                            </div>

                                            <div>
                                                <h4 className="text-xs font-black text-slate-700 uppercase tracking-wider mb-2">Descripción / Instrucciones del Comercial</h4>
                                                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 text-slate-700 text-sm leading-relaxed">
                                                    {selectedTask.DESCRIPCION || selectedTask.descripcion || 'Sin descripción adicional dada por la administración.'}
                                                </div>
                                            </div>
                                        </div>
                                    )}

                                    {detailTab === 'checklist' && (
                                        <div className="space-y-6 animate-in fade-in">
                                            <div className="flex justify-between items-center bg-slate-50 p-4 rounded-2xl border border-slate-200">
                                                <div>
                                                    <h4 className="text-sm font-black text-slate-800">Lista de Verificación de la Visita</h4>
                                                    <p className="text-xs text-slate-500">Marca las actividades realizadas durante la atención comercial.</p>
                                                </div>
                                                <span className="px-3 py-1 bg-indigo-100 text-indigo-800 text-xs font-black rounded-full">
                                                    {getTaskChecklist(selectedTask).filter(c => c.completed).length} / {getTaskChecklist(selectedTask).length}
                                                </span>
                                            </div>

                                            <div className="space-y-2">
                                                {getTaskChecklist(selectedTask).map((item, idx) => (
                                                    <div
                                                        key={item.id || idx}
                                                        onClick={() => handleToggleChecklistItem(idx)}
                                                        className={`p-3.5 rounded-2xl border transition-all cursor-pointer flex items-center justify-between gap-3 ${item.completed ? 'bg-emerald-50/60 border-emerald-200 text-emerald-900' : 'bg-white border-slate-200 hover:border-indigo-300'}`}
                                                    >
                                                        <div className="flex items-center gap-3">
                                                            <div className={`w-6 h-6 rounded-lg border flex items-center justify-center transition-all ${item.completed ? 'bg-emerald-600 border-emerald-600 text-white' : 'border-slate-300 bg-white'}`}>
                                                                {item.completed && <Icon name="CheckCircle" size={16} />}
                                                            </div>
                                                            <span className={`text-xs font-bold ${item.completed ? 'line-through opacity-80' : 'text-slate-800'}`}>{item.text}</span>
                                                        </div>
                                                        <span className="text-[10px] uppercase font-black tracking-wider opacity-60">{item.completed ? 'Completado' : 'Pendiente'}</span>
                                                    </div>
                                                ))}
                                            </div>

                                            <div className="flex gap-2 pt-2">
                                                <input
                                                    type="text"
                                                    value={newChecklistText}
                                                    onChange={e => setNewChecklistText(e.target.value)}
                                                    placeholder="Agregar nuevo ítem de verificación..."
                                                    className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                                />
                                                <button
                                                    onClick={handleAddChecklistItem}
                                                    className="px-4 py-2 bg-slate-900 hover:bg-indigo-900 text-white font-bold text-xs uppercase rounded-xl transition-colors shrink-0 cursor-pointer"
                                                >
                                                    + Agregar
                                                </button>
                                            </div>
                                        </div>
                                    )}

                                    {detailTab === 'evidencia' && (
                                        <div className="space-y-6 animate-in fade-in">
                                            <div className="bg-slate-900 text-white p-5 rounded-2xl shadow-md space-y-3">
                                                <div className="flex items-center justify-between">
                                                    <span className="text-xs font-black uppercase tracking-wider text-emerald-400 flex items-center gap-1.5">
                                                        <Icon name="MapPin" size={16} /> GPS Automático (No Modificable)
                                                    </span>
                                                    <button
                                                        onClick={captureGPS}
                                                        disabled={geoLoc.loading}
                                                        className="px-3 py-1 bg-white/10 hover:bg-white/20 text-white rounded-lg text-[10px] font-bold uppercase transition-colors flex items-center gap-1 cursor-pointer"
                                                    >
                                                        <Icon name="RefreshCw" size={12} className={geoLoc.loading ? 'animate-spin' : ''} /> Actualizar Coordenadas
                                                    </button>
                                                </div>

                                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-1">
                                                    <div>
                                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Latitud</label>
                                                        <input
                                                            type="text"
                                                            readOnly={true}
                                                            value={geoLoc.lat || (geoLoc.loading ? 'Consultando GPS...' : 'Sin GPS')}
                                                            className="w-full px-3 py-2 bg-white/10 text-emerald-300 font-mono font-bold text-xs rounded-xl border border-white/10 cursor-not-allowed"
                                                        />
                                                    </div>
                                                    <div>
                                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Longitud</label>
                                                        <input
                                                            type="text"
                                                            readOnly={true}
                                                            value={geoLoc.lon || (geoLoc.loading ? 'Consultando GPS...' : 'Sin GPS')}
                                                            className="w-full px-3 py-2 bg-white/10 text-emerald-300 font-mono font-bold text-xs rounded-xl border border-white/10 cursor-not-allowed"
                                                        />
                                                    </div>
                                                    <div>
                                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Precisión GPS</label>
                                                        <input
                                                            type="text"
                                                            readOnly={true}
                                                            value={geoLoc.accuracy ? `± ${geoLoc.accuracy} m` : 'N/A'}
                                                            className="w-full px-3 py-2 bg-white/10 text-indigo-200 font-mono font-bold text-xs rounded-xl border border-white/10 cursor-not-allowed"
                                                        />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="space-y-4 bg-slate-50 p-5 rounded-2xl border border-slate-200">
                                                <h4 className="text-xs font-black text-slate-800 uppercase tracking-wider">Subir Nueva Fotografía de Evidencia</h4>

                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="block text-[11px] font-bold text-slate-700 uppercase mb-1">Categoría de Evidencia</label>
                                                        <select
                                                            value={evidenceType}
                                                            onChange={e => setEvidenceType(e.target.value)}
                                                            className="w-full p-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:outline-none"
                                                        >
                                                            <option value="Fachada de Tienda">Fachada de Tienda</option>
                                                            <option value="Material POP">Material POP</option>
                                                            <option value="Inventario de Equipos">Inventario de Equipos</option>
                                                            <option value="Soporte de Pago/Recaudo">Soporte de Pago / Recaudo</option>
                                                            <option value="Acta de Visita">Acta de Visita / Firma</option>
                                                            <option value="Otros">Otros</option>
                                                        </select>
                                                    </div>

                                                    <div>
                                                        <label className="block text-[11px] font-bold text-slate-700 uppercase mb-1">Seleccionar o Tomar Foto</label>
                                                        <input
                                                            type="file"
                                                            accept="image/*"
                                                            capture="environment"
                                                            onChange={handleImageUpload}
                                                            className="w-full text-xs text-slate-500 file:mr-3 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-xs file:font-bold file:bg-indigo-600 file:text-white hover:file:bg-indigo-700 cursor-pointer"
                                                        />
                                                    </div>
                                                </div>

                                                {evidenceImg && (
                                                    <div className="relative rounded-2xl overflow-hidden border border-slate-200 max-h-56 bg-black flex items-center justify-center">
                                                        <img src={evidenceImg} alt="Preview Evidencia" className="max-h-56 object-contain" />
                                                        <button
                                                            onClick={() => setEvidenceImg('')}
                                                            className="absolute top-2 right-2 bg-rose-600 text-white p-1.5 rounded-full shadow-md hover:bg-rose-700 cursor-pointer"
                                                        >
                                                            <Icon name="X" size={16} />
                                                        </button>
                                                    </div>
                                                )}

                                                <div>
                                                    <label className="block text-[11px] font-bold text-slate-700 uppercase mb-1">Notas / Observaciones de la Foto</label>
                                                    <input
                                                        type="text"
                                                        value={evidenceNotes}
                                                        onChange={e => setEvidenceNotes(e.target.value)}
                                                        placeholder="Ej. Exhibición principal con 10 afiches colocados..."
                                                        className="w-full p-2.5 bg-white border border-slate-200 rounded-xl text-xs font-medium focus:outline-none"
                                                    />
                                                </div>

                                                <button
                                                    onClick={handleSaveEvidencia}
                                                    disabled={submittingEvidencia || !geoLoc.lat || !evidenceImg}
                                                    className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white font-black text-xs uppercase tracking-wider rounded-xl transition-all shadow-md flex items-center justify-center gap-2 cursor-pointer"
                                                >
                                                    <Icon name="Save" size={16} />
                                                    <span>{submittingEvidencia ? 'Guardando en BD (trop_fotos_gps)...' : 'Guardar Evidencia con GPS Obligatorio'}</span>
                                                </button>
                                            </div>

                                            {evidencesForSelected.length > 0 && (
                                                <div className="space-y-3 pt-2">
                                                    <h4 className="text-xs font-black text-slate-800 uppercase tracking-wider">Evidencias Registradas ({evidencesForSelected.length})</h4>
                                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                        {evidencesForSelected.map((ev, i) => (
                                                            <div key={ev.ID_EVIDENCIA || i} className="bg-white rounded-2xl border border-slate-200 p-3 space-y-2 shadow-sm">
                                                                <div className="h-40 rounded-xl overflow-hidden bg-slate-900 flex items-center justify-center">
                                                                    <img src={ev.IMAGEN_URL_O_BASE64 || ev.imagen_url_o_base64} alt="Evidencia" className="h-full object-cover w-full" />
                                                                </div>
                                                                <div className="space-y-1 text-xs">
                                                                    <div className="flex justify-between font-bold text-slate-800">
                                                                        <span>{ev.TIPO_EVIDENCIA || ev.tipo_evidencia}</span>
                                                                        <span className="text-[10px] text-slate-400">{ev.FECHA_CAPTURA || ev.fecha_captura}</span>
                                                                    </div>
                                                                    <p className="text-[11px] text-slate-500 font-mono flex items-center gap-1">
                                                                        <Icon name="MapPin" size={12} className="text-emerald-600" />
                                                                        <span>{ev.LATITUD || ev.latitud}, {ev.LONGITUD || ev.longitud}</span>
                                                                    </p>
                                                                    {ev.NOTAS || ev.notas ? <p className="text-[11px] text-slate-600 italic">"{ev.NOTAS || ev.notas}"</p> : null}
                                                                </div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )}

                                    {detailTab === 'monitoreo' && (
                                        <div className="space-y-6 animate-in fade-in">
                                            <div className="bg-slate-900 text-white p-5 rounded-2xl shadow-md space-y-2">
                                                <div className="flex items-center justify-between">
                                                    <span className="text-xs font-black uppercase tracking-wider text-emerald-400 flex items-center gap-1.5">
                                                        <Icon name="MapPin" size={16} /> Control de Tiempos y GPS
                                                    </span>
                                                    <button onClick={captureGPS} className="text-[10px] font-bold text-indigo-300 underline cursor-pointer">
                                                        Refrescar GPS
                                                    </button>
                                                </div>
                                                <p className="text-xs text-slate-300">
                                                    Coordenadas actuales: <strong className="font-mono text-white">{geoLoc.lat || 'Sin GPS'}, {geoLoc.lon || ''}</strong> (Precisión: {geoLoc.accuracy ? `${geoLoc.accuracy} m` : 'N/A'})
                                                </p>
                                            </div>

                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <button
                                                    onClick={handleCheckIn}
                                                    disabled={submittingAction || !geoLoc.lat}
                                                    className="p-6 bg-gradient-to-br from-emerald-500 to-teal-700 hover:from-emerald-600 hover:to-teal-800 disabled:opacity-50 text-white rounded-2xl shadow-lg transition-all text-left space-y-2 group cursor-pointer"
                                                >
                                                    <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center">
                                                        <Icon name="Play" size={20} />
                                                    </div>
                                                    <div>
                                                        <span className="text-xs font-black uppercase tracking-wider block opacity-90">Paso 1</span>
                                                        <h4 className="text-lg font-black">Registrar Check-in</h4>
                                                        <p className="text-xs opacity-80 mt-1">Marca el inicio de la atención en tienda.</p>
                                                    </div>
                                                </button>

                                                <button
                                                    onClick={handleCheckOut}
                                                    disabled={submittingAction || !geoLoc.lat}
                                                    className="p-6 bg-gradient-to-br from-indigo-600 to-slate-900 hover:from-indigo-700 hover:to-slate-950 disabled:opacity-50 text-white rounded-2xl shadow-lg transition-all text-left space-y-2 group cursor-pointer"
                                                >
                                                    <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center">
                                                        <Icon name="Square" size={20} />
                                                    </div>
                                                    <div>
                                                        <span className="text-xs font-black uppercase tracking-wider block opacity-90">Paso 2</span>
                                                        <h4 className="text-lg font-black">Registrar Check-out</h4>
                                                        <p className="text-xs opacity-80 mt-1">Calcula la duración total de la visita.</p>
                                                    </div>
                                                </button>
                                            </div>

                                            <div>
                                                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">Observaciones de la Gestión</label>
                                                <textarea
                                                    rows="3"
                                                    value={checkinObs}
                                                    onChange={e => setCheckinObs(e.target.value)}
                                                    placeholder="Anota acuerdos con el aliado, compromisos o detalles..."
                                                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                                />
                                            </div>

                                            {activeVisitForSelected && (
                                                <div className="bg-slate-50 p-5 rounded-2xl border border-slate-200 space-y-3">
                                                    <h4 className="text-xs font-black text-slate-800 uppercase tracking-wider">Historial de Monitoreo de esta Visita</h4>
                                                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
                                                        <div className="bg-white p-3 rounded-xl border border-slate-100">
                                                            <span className="text-[10px] text-slate-400 font-bold block uppercase">Check-in</span>
                                                            <span className="font-bold text-slate-800">{activeVisitForSelected.CHECKIN_FECHA || activeVisitForSelected.checkin_fecha || 'Pendiente'}</span>
                                                        </div>
                                                        <div className="bg-white p-3 rounded-xl border border-slate-100">
                                                            <span className="text-[10px] text-slate-400 font-bold block uppercase">Check-out</span>
                                                            <span className="font-bold text-slate-800">{activeVisitForSelected.CHECKOUT_FECHA || activeVisitForSelected.checkout_fecha || 'En proceso...'}</span>
                                                        </div>
                                                        <div className="bg-white p-3 rounded-xl border border-slate-100">
                                                            <span className="text-[10px] text-slate-400 font-bold block uppercase">Duración</span>
                                                            <span className="font-bold text-indigo-600">{activeVisitForSelected.DURACION_MINUTOS || activeVisitForSelected.duracion_minutos || 0} min</span>
                                                        </div>
                                                        <div className="bg-white p-3 rounded-xl border border-slate-100">
                                                            <span className="text-[10px] text-slate-400 font-bold block uppercase">Retraso Detectado</span>
                                                            <span className="font-bold text-amber-600">{activeVisitForSelected.RETRASO_MINUTOS || activeVisitForSelected.retraso_minutos || 0} min</span>
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            );
        };

        const SecurityView = ({ db, setDb, apiCall, showToast, userPerms }) => {
            const modulesList = [
                { id: 'agenda', name: 'Agenda y Gestión de Visitas', icon: 'Calendar' },
                { id: 'sim', name: 'Calculadora (Inicio)', icon: 'Calculator' },
                { id: 'ext', name: 'Crédito en Línea', icon: 'Smartphone' },
                { id: 'sol', name: 'Solicitudes', icon: 'ClipboardList' },
                { id: 'tablero', name: 'Tablero Cartera', icon: 'BarChart2' },
                { id: 'consultapayjoy', name: 'Consulta PayJoy', icon: 'Search' },
                { id: 'liq', name: 'Liquidaciones', icon: 'FileText' },
                { id: 'retailb', name: 'Retail B', icon: 'Store' },
                { id: 'dash', name: 'Panel de Rendimiento', icon: 'Globe' },
                { id: 'prestamos', name: 'Gestión de Préstamos', icon: 'Handshake' },
                { 
                    id: 'tes', 
                    name: 'Caja y Tesorería', 
                    icon: 'Landmark',
                    tabs: [
                        { id: 'pendientes', label: 'Solicitudes Pendientes' },
                        { id: 'historial', label: 'Historial de Tesorería' }
                    ]
                },
                { 
                    id: 'con', 
                    name: 'Consultas Generales', 
                    icon: 'FileText',
                    tabs: [
                        { id: 'historial', label: 'Historial de Créditos' },
                        { id: 'aliados', label: 'Aliados Comerciales' },
                        { id: 'roles', label: 'Usuarios / Roles' },
                        { id: 'unidades', label: 'Unidades' },
                        { id: 'entidades', label: 'Entidades Financieras' }
                    ]
                },
                { 
                    id: 'adm', 
                    name: 'Configuración Admin', 
                    icon: 'Settings',
                    tabs: [
                        { id: 'aliados', label: 'Gestión de Aliados' },
                        { id: 'roles', label: 'Gestión de Roles/Usuarios' },
                        { id: 'entidades', label: 'Gestión de Entidades' },
                        { id: 'anuncios', label: 'Gestión de Anuncios' }
                    ]
                },
                { id: 'consola', name: 'Consola de Equipos / Catálogo', icon: 'Database' },
                { id: 'seguridad', name: 'Módulo de Seguridad', icon: 'ShieldCheck' }
            ];

            const defaultUserTypes = ['CIA', 'ADMIN', 'TESORERO', 'CARTERA', 'SUPERVISOR'];

            const [userTypesConfig, setUserTypesConfig] = useState(() => {
                const setTypes = new Set(defaultUserTypes);
                if (db.config_permisos && Array.isArray(db.config_permisos)) {
                    db.config_permisos.forEach(p => {
                        if (p.TIPO_USUARIO && p.TIPO_USUARIO !== 'ADMINISTRADOR') {
                            setTypes.add(String(p.TIPO_USUARIO).toUpperCase().trim());
                        }
                    });
                }
                if (db.clientes && Array.isArray(db.clientes)) {
                    db.clientes.forEach(c => {
                        const name = String(c.nombre_cliente || '').trim();
                        if (name && name.toLowerCase() !== 'administrador' && name.includes('-')) {
                            const prefix = name.split('-')[0].toUpperCase().trim();
                            if (prefix) setTypes.add(prefix);
                        }
                    });
                }
                return Array.from(setTypes);
            });

            const [selectedUserType, setSelectedUserType] = useState('CIA');
            const [newUserType, setNewUserType] = useState('');
            const [isSaving, setIsSaving] = useState(false);
            const [deleteModal, setDeleteModal] = useState({ show: false, userType: null });

            const [permissionsState, setPermissionsState] = useState({});

            useEffect(() => {
                const initialState = {};
                userTypesConfig.forEach(ut => {
                    initialState[ut] = {};
                    modulesList.forEach(m => {
                        initialState[ut][m.id] = {
                            enabled: false,
                            tabs: m.tabs ? m.tabs.map(t => t.id) : []
                        };
                    });
                });

                if (db.config_permisos && Array.isArray(db.config_permisos) && db.config_permisos.length > 0) {
                    db.config_permisos.forEach(item => {
                        const ut = String(item.TIPO_USUARIO || '').toUpperCase().trim();
                        const modId = item.MODULO;
                        const tabId = item.PESTANA;
                        const ver = item.VER === true || String(item.VER).toLowerCase() === 'true';

                        if (ut && ut !== 'ADMINISTRADOR' && initialState[ut] && initialState[ut][modId]) {
                            if (ver) {
                                initialState[ut][modId].enabled = true;
                                const modDef = modulesList.find(m => m.id === modId);
                                if (modDef && modDef.tabs) {
                                    if (tabId === 'TODAS') {
                                        initialState[ut][modId].tabs = modDef.tabs.map(t => t.id);
                                    } else {
                                        if (!initialState[ut][modId].tabs.includes(tabId)) {
                                            initialState[ut][modId].tabs.push(tabId);
                                        }
                                    }
                                }
                            }
                        }
                    });
                } else {
                    userTypesConfig.forEach(ut => {
                        modulesList.forEach(m => {
                            initialState[ut][m.id].enabled = true;
                        });
                    });
                }

                setPermissionsState(initialState);
            }, [db.config_permisos, userTypesConfig]);

            const handleAddUserType = (e) => {
                e.preventDefault();
                const sanitized = newUserType.toUpperCase().trim().replace(/[^A-Z0-9_]/g, '');
                if (!sanitized) {
                    showToast("Ingresa un nombre válido para el tipo de usuario.", "error");
                    return;
                }
                if (sanitized === 'ADMINISTRADOR') {
                    showToast("El perfil ADMINISTRADOR es reservado e inamovible.", "error");
                    return;
                }
                if (userTypesConfig.includes(sanitized)) {
                    showToast("Ese tipo de usuario ya existe.", "error");
                    return;
                }

                const updatedTypes = [...userTypesConfig, sanitized];
                setUserTypesConfig(updatedTypes);
                setPermissionsState(prev => ({
                    ...prev,
                    [sanitized]: modulesList.reduce((acc, m) => {
                        acc[m.id] = { enabled: true, tabs: m.tabs ? m.tabs.map(t => t.id) : [] };
                        return acc;
                    }, {})
                }));
                setSelectedUserType(sanitized);
                setNewUserType('');
                showToast(`Tipo de usuario "${sanitized}" creado.`, "success");
            };

            const confirmDeleteUserType = () => {
                const utToDelete = deleteModal.userType;
                if (!utToDelete) return;
                const updated = userTypesConfig.filter(u => u !== utToDelete);
                setUserTypesConfig(updated);
                setPermissionsState(prev => {
                    const next = { ...prev };
                    delete next[utToDelete];
                    return next;
                });
                if (selectedUserType === utToDelete) {
                    setSelectedUserType(updated[0] || 'CIA');
                }
                setDeleteModal({ show: false, userType: null });
                showToast(`Tipo de usuario "${utToDelete}" eliminado.`, "info");
            };

            const toggleModule = (modId) => {
                if (selectedUserType === 'ADMINISTRADOR') return;
                setPermissionsState(prev => {
                    const currentUt = prev[selectedUserType] || {};
                    const currentMod = currentUt[modId] || { enabled: false, tabs: [] };
                    const modDef = modulesList.find(m => m.id === modId);
                    const newEnabled = !currentMod.enabled;

                    return {
                        ...prev,
                        [selectedUserType]: {
                            ...currentUt,
                            [modId]: {
                                enabled: newEnabled,
                                tabs: newEnabled && modDef?.tabs ? modDef.tabs.map(t => t.id) : []
                            }
                        }
                    };
                });
            };

            const toggleTab = (modId, tabId) => {
                if (selectedUserType === 'ADMINISTRADOR') return;
                setPermissionsState(prev => {
                    const currentUt = prev[selectedUserType] || {};
                    const currentMod = currentUt[modId] || { enabled: true, tabs: [] };
                    const currentTabs = currentMod.tabs || [];
                    const hasTab = currentTabs.includes(tabId);
                    const newTabs = hasTab ? currentTabs.filter(t => t !== tabId) : [...currentTabs, tabId];

                    return {
                        ...prev,
                        [selectedUserType]: {
                            ...currentUt,
                            [modId]: {
                                ...currentMod,
                                enabled: newTabs.length > 0 ? true : currentMod.enabled,
                                tabs: newTabs
                            }
                        }
                    };
                });
            };

            const toggleAllModules = (enable) => {
                if (selectedUserType === 'ADMINISTRADOR') return;
                setPermissionsState(prev => {
                    const currentUt = prev[selectedUserType] || {};
                    const updatedUt = {};
                    modulesList.forEach(mod => {
                        updatedUt[mod.id] = {
                            enabled: enable,
                            tabs: enable && mod.tabs ? mod.tabs.map(t => t.id) : []
                        };
                    });
                    return {
                        ...prev,
                        [selectedUserType]: updatedUt
                    };
                });
            };

            const handleSave = async () => {
                setIsSaving(true);
                const payload = [];
                let permIdCounter = 1;
                
                const existingPermMap = new Map();
                if (db.config_permisos && Array.isArray(db.config_permisos)) {
                    db.config_permisos.forEach(p => {
                        const utKey = String(p.TIPO_USUARIO || '').toUpperCase().trim();
                        const modKey = String(p.MODULO || '').trim();
                        const pestKey = String(p.PESTANA || '').trim();
                        const existingId = p.ID_PERMISO || p.id_permiso || p.id || p.ID || p.cedula || p.CEDULA;
                        if (utKey && modKey && existingId) {
                            existingPermMap.set(`${utKey}_${modKey}_${pestKey}`, existingId);
                        }
                    });
                }

                const createPermItem = (idVal, utVal, modVal, pestanaVal) => ({
                    id: idVal,
                    ID: idVal,
                    id_permiso: idVal,
                    ID_PERMISO: idVal,
                    cedula: idVal,
                    CEDULA: idVal,
                    TIPO_USUARIO: utVal,
                    tipo_usuario: utVal,
                    MODULO: modVal,
                    modulo: modVal,
                    PESTANA: pestanaVal,
                    pestana: pestanaVal,
                    VER: true,
                    ver: true,
                    INTERACTUAR: true,
                    interactuar: true
                });

                const adminId = existingPermMap.get('ADMINISTRADOR_todos_TODAS') || 'PERM-0';
                payload.push(createPermItem(adminId, 'ADMINISTRADOR', 'todos', 'TODAS'));

                userTypesConfig.forEach(ut => {
                    if (ut === 'ADMINISTRADOR') return;
                    const config = permissionsState[ut] || {};
                    modulesList.forEach(mod => {
                        const isModEnabled = config[mod.id]?.enabled;
                        if (isModEnabled) {
                            if (mod.tabs && mod.tabs.length > 0) {
                                const selectedTabs = config[mod.id]?.tabs || [];
                                selectedTabs.forEach(tabId => {
                                    const key = `${ut}_${mod.id}_${tabId}`;
                                    const itemKey = existingPermMap.get(key) || `PERM-${Date.now()}-${permIdCounter++}`;
                                    payload.push(createPermItem(itemKey, ut, mod.id, tabId));
                                });
                            } else {
                                const key = `${ut}_${mod.id}_TODAS`;
                                const itemKey = existingPermMap.get(key) || `PERM-${Date.now()}-${permIdCounter++}`;
                                payload.push(createPermItem(itemKey, ut, mod.id, 'TODAS'));
                            }
                        }
                    });
                });

                if (setDb) {
                    setDb(prev => ({ ...prev, config_permisos: payload }));
                }
                const ok = await apiCall('guardarConfigPermisos', payload, "Configuración de seguridad guardada con éxito.");
                setIsSaving(false);
            };

            const isMasterAdmin = selectedUserType === 'ADMINISTRADOR';

            return (
                <div className="max-w-7xl mx-auto py-6 px-4 space-y-6 animate-fade-in pb-20">
                    <div className="bg-gradient-to-r from-slate-900 via-indigo-950 to-slate-900 rounded-3xl p-6 md:p-8 text-white shadow-xl flex flex-col md:flex-row md:items-center justify-between gap-6 border border-slate-800">
                        <div className="flex items-center gap-4">
                            <div className="w-14 h-14 bg-indigo-500/20 border border-indigo-400/30 rounded-2xl flex items-center justify-center text-indigo-400 shrink-0">
                                <Icon name="ShieldCheck" size={32} />
                            </div>
                            <div>
                                <h1 className="text-2xl md:text-3xl font-black tracking-tight">Módulo de Seguridad</h1>
                                <p className="text-indigo-200 text-xs md:text-sm font-medium mt-1">Gestión granular de roles, comodines de perfil y matriz de permisos por vista</p>
                            </div>
                        </div>

                        <button
                            onClick={handleSave}
                            disabled={isSaving}
                            className="px-6 py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm tracking-wide shadow-lg hover:shadow-indigo-500/25 transition-all flex items-center justify-center gap-2 disabled:opacity-50 shrink-0 cursor-pointer"
                        >
                            {isSaving ? <Icon name="RefreshCw" size={18} className="animate-spin" /> : <Icon name="Save" size={18} />}
                            {isSaving ? 'Guardando...' : 'Guardar Cambios'}
                        </button>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                        <div className="lg:col-span-4 bg-white rounded-3xl border border-slate-200 shadow-sm p-6 flex flex-col space-y-6">
                            <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                                <div className="flex items-center gap-2">
                                    <Icon name="Users" size={20} className="text-indigo-600" />
                                    <h2 className="font-black text-slate-800 text-lg">Tipos de Usuario</h2>
                                </div>
                                <span className="text-[10px] font-black uppercase tracking-widest bg-slate-100 text-slate-600 px-2.5 py-1 rounded-full">
                                    {userTypesConfig.length + 1} Roles
                                </span>
                            </div>

                            <form onSubmit={handleAddUserType} className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 block">
                                    Crear Nuevo Tipo / Perfil
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="text"
                                        value={newUserType}
                                        onChange={(e) => setNewUserType(e.target.value.toUpperCase())}
                                        placeholder="Ej: CARTERA_MED"
                                        className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-800 uppercase focus:outline-none focus:border-indigo-500 focus:bg-white transition-all placeholder:text-slate-400 placeholder:normal-case"
                                    />
                                    <button
                                        type="submit"
                                        className="px-4 py-2.5 bg-slate-900 hover:bg-indigo-600 text-white rounded-xl font-bold text-xs transition-colors flex items-center gap-1 shrink-0 cursor-pointer"
                                    >
                                        <Icon name="Plus" size={16} /> Agregar
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-400 font-medium">Se convertirá a mayúsculas sostenidas automáticamente.</p>
                            </form>

                            <div className="space-y-2 overflow-y-auto max-h-[500px] custom-scrollbar pr-1">
                                <div
                                    onClick={() => setSelectedUserType('ADMINISTRADOR')}
                                    className={`p-4 rounded-2xl border transition-all cursor-pointer relative overflow-hidden ${
                                        selectedUserType === 'ADMINISTRADOR'
                                            ? 'bg-gradient-to-r from-amber-500/10 to-amber-600/10 border-amber-500 shadow-md'
                                            : 'bg-slate-50 border-slate-200 hover:border-amber-300'
                                    }`}
                                >
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-9 h-9 bg-amber-500 text-white rounded-xl flex items-center justify-center font-black shadow-sm shrink-0">
                                                <Icon name="ShieldCheck" size={20} />
                                            </div>
                                            <div>
                                                <h3 className="font-black text-slate-900 text-sm">ADMINISTRADOR</h3>
                                                <p className="text-[11px] font-mono font-bold text-amber-700">Comodín: ADMINISTRADOR</p>
                                            </div>
                                        </div>
                                        <span className="bg-amber-100 text-amber-800 border border-amber-200 text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md">
                                            Maestro
                                        </span>
                                    </div>
                                </div>

                                {userTypesConfig.map(ut => {
                                    const isSelected = selectedUserType === ut;
                                    const utConfig = permissionsState[ut] || {};
                                    const enabledModsCount = Object.values(utConfig).filter(m => m.enabled).length;

                                    return (
                                        <div
                                            key={ut}
                                            onClick={() => setSelectedUserType(ut)}
                                            className={`p-4 rounded-2xl border transition-all cursor-pointer relative group ${
                                                isSelected
                                                    ? 'bg-indigo-50/70 border-indigo-500 shadow-sm'
                                                    : 'bg-white border-slate-200 hover:border-indigo-200 hover:bg-slate-50/50'
                                            }`}
                                        >
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-black text-xs transition-colors shrink-0 ${
                                                        isSelected ? 'bg-indigo-600 text-white shadow-sm' : 'bg-slate-100 text-slate-600'
                                                    }`}>
                                                        {ut.charAt(0)}
                                                    </div>
                                                    <div>
                                                        <h3 className="font-black text-slate-800 text-sm">{ut}</h3>
                                                        <p className="text-[11px] font-mono font-bold text-slate-500">
                                                            Formato: <span className="text-indigo-600">{ut}-***</span>
                                                        </p>
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full">
                                                        {enabledModsCount} Módulos
                                                    </span>
                                                    <button
                                                        type="button"
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            setDeleteModal({ show: true, userType: ut });
                                                        }}
                                                        className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-rose-600 p-1.5 rounded-lg hover:bg-rose-50 transition-all cursor-pointer"
                                                        title={`Eliminar perfil ${ut}`}
                                                    >
                                                        <Icon name="Trash2" size={16} />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        <div className="lg:col-span-8 bg-white rounded-3xl border border-slate-200 shadow-sm p-6 space-y-6">
                            <div className="bg-slate-50 rounded-2xl p-5 border border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                <div>
                                    <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600 block mb-0.5">Perfil Seleccionado</span>
                                    <h2 className="text-xl font-black text-slate-900 flex items-center gap-2">
                                        {selectedUserType}
                                        <span className="text-xs font-mono font-normal text-slate-500 bg-white border border-slate-200 px-2 py-0.5 rounded-md">
                                            Patrón: {isMasterAdmin ? 'ADMINISTRADOR' : `${selectedUserType}-***`}
                                        </span>
                                    </h2>
                                    <p className="text-xs text-slate-500 mt-1">
                                        {isMasterAdmin 
                                            ? 'Acceso total e irrestricto en todo el sistema.'
                                            : `Configura los permisos para todos los usuarios con prefijo "${selectedUserType}-" en su tienda.`}
                                    </p>
                                </div>

                                {!isMasterAdmin && (
                                    <div className="flex items-center gap-2 shrink-0">
                                        <button
                                            onClick={() => toggleAllModules(true)}
                                            className="px-3 py-1.5 bg-white border border-slate-200 hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-200 text-slate-700 rounded-xl text-xs font-bold transition-all shadow-sm cursor-pointer"
                                        >
                                            Marcar Todos
                                        </button>
                                        <button
                                            onClick={() => toggleAllModules(false)}
                                            className="px-3 py-1.5 bg-white border border-slate-200 hover:bg-rose-50 hover:text-rose-600 hover:border-rose-200 text-slate-700 rounded-xl text-xs font-bold transition-all shadow-sm cursor-pointer"
                                        >
                                            Desmarcar Todos
                                        </button>
                                    </div>
                                )}
                            </div>

                            {isMasterAdmin && (
                                <div className="bg-amber-50 border border-amber-200 text-amber-800 p-4 rounded-2xl flex items-start gap-3">
                                    <Icon name="ShieldCheck" size={24} className="text-amber-600 shrink-0 mt-0.5" />
                                    <p className="text-xs font-semibold leading-relaxed">
                                        El perfil <strong>ADMINISTRADOR</strong> es maestro e inamovible. Siempre mantiene acceso total e irrestricto (<code className="bg-amber-100 px-1 py-0.5 rounded text-[11px]">MODULO: 'todos'</code>, <code className="bg-amber-100 px-1 py-0.5 rounded text-[11px]">PESTANA: 'TODAS'</code>). No se pueden restringir sus permisos.
                                    </p>
                                </div>
                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {modulesList.map(mod => {
                                    const modState = isMasterAdmin
                                        ? { enabled: true, tabs: mod.tabs ? mod.tabs.map(t => t.id) : [] }
                                        : (permissionsState[selectedUserType]?.[mod.id] || { enabled: false, tabs: [] });

                                    const isEnabled = modState.enabled;

                                    return (
                                        <div
                                            key={mod.id}
                                            className={`rounded-2xl border transition-all p-4 ${
                                                isEnabled
                                                    ? 'bg-white border-slate-200 shadow-sm'
                                                    : 'bg-slate-50/70 border-slate-200/80 opacity-75'
                                            }`}
                                        >
                                            <div className="flex items-center justify-between gap-3">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center transition-colors shrink-0 ${
                                                        isEnabled ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-200/60 text-slate-400'
                                                    }`}>
                                                        <Icon name={mod.icon} size={18} />
                                                    </div>
                                                    <div>
                                                        <h4 className="font-black text-slate-800 text-xs md:text-sm">{mod.name}</h4>
                                                        <span className="text-[10px] font-mono text-slate-400">ID: {mod.id}</span>
                                                    </div>
                                                </div>

                                                <label className={`relative inline-flex items-center cursor-pointer ${isMasterAdmin ? 'pointer-events-none opacity-80' : ''}`}>
                                                    <input
                                                        type="checkbox"
                                                        checked={isEnabled}
                                                        disabled={isMasterAdmin}
                                                        onChange={() => toggleModule(mod.id)}
                                                        className="sr-only peer"
                                                    />
                                                    <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                                                </label>
                                            </div>

                                            {mod.tabs && mod.tabs.length > 0 && isEnabled && (
                                                <div className="mt-4 pt-3 border-t border-slate-100 space-y-2 bg-slate-50/80 p-3 rounded-xl">
                                                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Pestañas Internas Permitidas:</p>
                                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                                        {mod.tabs.map(tab => {
                                                            const isTabChecked = modState.tabs?.includes(tab.id);
                                                            return (
                                                                <label
                                                                    key={tab.id}
                                                                    title={tab.label}
                                                                    className={`flex items-center gap-2 p-2 rounded-lg text-xs font-bold transition-all cursor-pointer relative group/tab ${
                                                                        isTabChecked
                                                                            ? 'bg-white text-slate-800 border border-slate-200 shadow-2xs'
                                                                            : 'text-slate-400 hover:text-slate-600'
                                                                    } ${isMasterAdmin ? 'pointer-events-none' : ''}`}
                                                                >
                                                                    <input
                                                                        type="checkbox"
                                                                        checked={isMasterAdmin || isTabChecked}
                                                                        disabled={isMasterAdmin}
                                                                        onChange={() => toggleTab(mod.id, tab.id)}
                                                                        className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4 shrink-0"
                                                                    />
                                                                    <span className="truncate" title={tab.label}>{tab.label}</span>
                                                                    {/* Tooltip flotante al pasar el mouse */}
                                                                    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 hidden group-hover/tab:flex flex-col items-center z-30 pointer-events-none whitespace-nowrap">
                                                                        <div className="bg-slate-900 text-white text-[11px] font-black px-2.5 py-1 rounded-lg shadow-xl border border-slate-700">
                                                                            {tab.label}
                                                                        </div>
                                                                        <div className="w-2 h-2 bg-slate-900 rotate-45 -mt-1 border-r border-b border-slate-700"></div>
                                                                    </div>
                                                                </label>
                                                            );
                                                        })}
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    {deleteModal.show && (
                        <div className="fixed inset-0 z-[8000] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in">
                            <div className="bg-white rounded-3xl max-w-md w-full p-6 shadow-2xl border border-slate-200 space-y-4 animate-pop-in">
                                <div className="w-12 h-12 bg-rose-100 text-rose-600 rounded-2xl flex items-center justify-center mx-auto">
                                    <Icon name="Trash2" size={24} />
                                </div>
                                <div className="text-center">
                                    <h3 className="text-lg font-black text-slate-900">¿Eliminar Tipo de Usuario?</h3>
                                    <p className="text-xs text-slate-500 mt-2 leading-relaxed">
                                        Estás a punto de eliminar el perfil <strong className="text-slate-800">{deleteModal.userType}</strong>. Esta acción revocará los permisos de este tipo de perfil al guardar la configuración.
                                    </p>
                                </div>
                                <div className="flex gap-3 pt-2">
                                    <button
                                        onClick={() => setDeleteModal({ show: false, userType: null })}
                                        className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs transition-colors cursor-pointer"
                                    >
                                        Cancelar
                                    </button>
                                    <button
                                        onClick={confirmDeleteUserType}
                                        className="flex-1 py-3 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold text-xs transition-colors shadow-sm cursor-pointer"
                                    >
                                        Eliminar Perfil
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            );
        };

        const App = () => {
            const [currentUser, setCurrentUser] = useState(() => {
                const savedSession = sessionStorage.getItem('soluciones_user_session_v4');
                if (savedSession) {
                    try {
                        return JSON.parse(savedSession);
                    } catch (e) {
                        sessionStorage.removeItem('soluciones_user_session_v4');
                        return null;
                    }
                }
                return null;
            });
            const [userPerms, setUserPerms] = useState({ isGlobalAdmin: false, isRegionalAdmin: false, isSemiAdmin: false, isTesoreria: false, hasPrivileges: false, un: '' });
            
            const [db, setDb] = useState({ clientes: [], financieras: [], cuotas: [], porcentajes: [], simulaciones: [], roles: [], roles_permisos: [], bancos: [], cuentas_tesoreria: [], config_permisos: [], notificacion: null });
            const [distribuidorPrices, setDistribuidorPrices] = useState([]);
            
            const [activeView, setActiveView] = useState('tablero'); 
            const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
            
            const [loading, setLoading] = useState(false);
            const [initialLoading, setInitialLoading] = useState(true);
            const [loginLoading, setLoginLoading] = useState(false);
            const [toast, setToast] = useState({ show: false, message: '', type: 'success' });
            
            const [qrModal, setQrModal] = useState({ show: false, url: '', title: '' });
            const [preciosModal, setPreciosModal] = useState({ show: false, loading: false });

            const showToast = useCallback((message, type = 'success') => {
                setToast({ show: true, message, type });
                setTimeout(() => setToast({ show: false, message: '', type: 'success' }), 3500);
            }, []);

            const setupPermissions = useCallback((user, configPermisos = db.config_permisos) => {
                if (!user) return;
                const rawName = String(user.nombre_cliente || '').trim();
                const uName = rawName.toLowerCase();
                const isGlobalAdmin = uName === 'administrador';
                
                let userType = 'CIA';
                if (isGlobalAdmin) {
                    userType = 'ADMINISTRADOR';
                } else if (rawName.includes('-')) {
                    userType = rawName.split('-')[0].toUpperCase().trim();
                } else {
                    userType = rawName.toUpperCase().trim();
                }

                const hasPrivileges = isGlobalAdmin || uName.startsWith('admin-') || uName.startsWith('cia') || uName.startsWith('tesoreria') || uName.startsWith('cartera') || uName.startsWith('supervisor');

                const modulosPermitidos = {};
                const pestanasPermitidas = {};
                const allModuleIds = ['sim', 'ext', 'agenda', 'sol', 'tablero', 'consultapayjoy', 'liq', 'retailb', 'dash', 'prestamos', 'tes', 'con', 'adm', 'consola', 'seguridad'];

                if (isGlobalAdmin || !configPermisos || !Array.isArray(configPermisos) || configPermisos.length === 0) {
                    allModuleIds.forEach(id => {
                        if (isGlobalAdmin) {
                            modulosPermitidos[id] = true;
                            pestanasPermitidas[id] = ['TODAS'];
                        } else {
                            if (id === 'sim' || id === 'ext') {
                                modulosPermitidos[id] = true;
                            } else if (id === 'tes' || id === 'con') {
                                modulosPermitidos[id] = (uName === 'tesoreria' || uName === 'tesorería' || uName.startsWith('admin-') || isGlobalAdmin);
                            } else {
                                modulosPermitidos[id] = hasPrivileges;
                            }
                            pestanasPermitidas[id] = ['TODAS'];
                        }
                    });
                } else {
                    const userRules = configPermisos.filter(r => 
                        String(r.TIPO_USUARIO).toUpperCase().trim() === userType
                    );

                    const hasAllAccess = userRules.some(r => r.MODULO === 'todos' && (r.VER === true || String(r.VER).toLowerCase() === 'true'));

                    allModuleIds.forEach(id => {
                        if (id === 'sim' || id === 'ext') {
                            modulosPermitidos[id] = true;
                            pestanasPermitidas[id] = ['TODAS'];
                            return;
                        }

                        if (hasAllAccess) {
                            modulosPermitidos[id] = true;
                            pestanasPermitidas[id] = ['TODAS'];
                        } else {
                            const modRules = userRules.filter(r => r.MODULO === id && (r.VER === true || String(r.VER).toLowerCase() === 'true'));
                            if (modRules.length > 0) {
                                modulosPermitidos[id] = true;
                                pestanasPermitidas[id] = modRules.map(r => r.PESTANA);
                            } else {
                                modulosPermitidos[id] = false;
                                pestanasPermitidas[id] = [];
                            }
                        }
                    });
                }

                const canAccessModule = (modId) => {
                    if (modId === 'tablero' || modId === 'consultapayjoy') return true;
                    if (isGlobalAdmin) return true;
                    return Boolean(modulosPermitidos[modId]);
                };

                const canAccessTab = (modId, tabId) => {
                    if (isGlobalAdmin) return true;
                    if (!modulosPermitidos[modId]) return false;
                    const allowedTabs = pestanasPermitidas[modId] || [];
                    return allowedTabs.includes('TODAS') || allowedTabs.includes(tabId);
                };

                setUserPerms({
                    isGlobalAdmin,
                    isRegionalAdmin: uName.startsWith('admin-'),
                    isSemiAdmin: uName.startsWith('cia'),
                    isTesoreria: uName === 'tesoreria' || uName === 'tesorería',
                    hasPrivileges,
                    userType,
                    un: user.un || user.UN || user.UnidaddeNegocio || user['UNIDAD DE NEGOCIO'] || user['Unidad de Negocio'] || '',
                    modulos: modulosPermitidos,
                    pestanas: pestanasPermitidas,
                    canAccessModule,
                    canAccessTab
                });
            }, [db.config_permisos]);

            const fetchUsersLocal = useCallback(async () => {
                const hasSession = !!sessionStorage.getItem('soluciones_user_session_v4');
                
                try {
                    const cachedDb = localStorage.getItem('soluciones_db_cache_v4');
                    if (cachedDb) {
                        setDb(JSON.parse(cachedDb));
                        setInitialLoading(false);
                        if (hasSession) {
                            fetchData(false, true); // background sync
                        }
                    } else {
                        // If no cache, fetch everything
                        fetchData(false, false);
                    }
                } catch(e) {
                   console.error("Failed to load local DB", e);
                   fetchData(false, false);
                }
            }, []);

            const fetchData = useCallback(async (isRefresh = false, isBackground = false) => {
                if (!isBackground) setLoading(true);
                let resJson = null;
                let retries = 3;
                
                while (retries > 0 && !resJson) {
                    try {
                        const separator = SCRIPT_URL.includes('?') ? '&' : '?';
                        const response = await fetch(`${SCRIPT_URL}${separator}action=getData`, { method: 'GET', mode: 'cors' });
                        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}. Verifica que el Web App de Google Apps Script esté público (Anyone).`);
                        resJson = await response.json();
                        
                        if (resJson.status === 'success' && resJson.data) {
                            const lastVersion = localStorage.getItem('last_backend_version');
                            if (resJson.data.version && lastVersion && lastVersion !== resJson.data.version) {
                                console.log("New version detected, clearing cache...");
                                localStorage.removeItem('soluciones_db_cache_v4');
                                localStorage.removeItem('soluciones_catalog_cache');
                                localStorage.setItem('last_backend_version', resJson.data.version);
                                window.location.reload(true);
                                return;
                            }
                            if (resJson.data.version) {
                                localStorage.setItem('last_backend_version', resJson.data.version);
                            }
                            setDb(resJson.data);
                            localStorage.setItem('soluciones_db_cache_v4', JSON.stringify(resJson.data));
                            if(isRefresh) showToast("Datos sincronizados.", "success");
                        } else {
                            throw new Error(resJson.message || "Failed to load DB");
                        }
                    } catch (error) {
                        retries--;
                        if (retries > 0) await new Promise(r => setTimeout(r, 1500));
                        else {
                            console.error("Fetch Data Error:", error);
                            if (!isBackground) showToast(error.message || "Error de conexión. Intenta de nuevo.", "error");
                        }
                    }
                }
                if (!isBackground) setLoading(false);
                setInitialLoading(false);
            }, [showToast]);

            useEffect(() => {
                fetchUsersLocal();
            }, [fetchUsersLocal]);

            useEffect(() => {
                if (currentUser) {
                    setupPermissions(currentUser, db.config_permisos);
                }
            }, [currentUser, db.config_permisos, setupPermissions]);

            useEffect(() => {
                if (currentUser) {
                    const interval = setInterval(() => { fetchData(false, true); }, 300000);
                    return () => clearInterval(interval);
                }
            }, [currentUser, fetchData]);

            const handleLogin = async (user, pass) => {
                setLoginLoading(true);
                
                const f = db.clientes.find(c => String(c.nombre_cliente).toLowerCase().trim() === user.toLowerCase().trim() && String(c.contrasena) === pass);
                
                if (f) {
                    setCurrentUser(f);
                    setupPermissions(f, db.config_permisos);
                    sessionStorage.setItem('soluciones_user_session_v4', JSON.stringify(f));
                    setActiveView('tablero');
                    fetchData(); // Trigger full data load now
                } else {
                    showToast("Credenciales incorrectas o usuario no existe.", "error");
                }
                setLoginLoading(false);
            };

            const handleLogout = () => {
                setCurrentUser(null);
                setUserPerms({ isGlobalAdmin: false, isRegionalAdmin: false, isSemiAdmin: false, isTesoreria: false, hasPrivileges: false, un: '' });
                sessionStorage.removeItem('soluciones_user_session_v4');
                setActiveView('tablero');
            };

            const apiCall = async (action, data, successMsg) => {
                setLoading(true);
                try {
                    const jsonPayload = data ? JSON.stringify(data) : '';
                    const separator = SCRIPT_URL.includes('?') ? '&' : '?';
                    const targetUrl = `${SCRIPT_URL}${separator}action=${action}`;
                    let resJson = null;

                    // Always try GET first as Apps Script doGet(e) handles action & data in query params
                    try {
                        const payloadParam = jsonPayload ? `&data=${encodeURIComponent(jsonPayload)}` : '';
                        const response = await fetch(`${targetUrl}${payloadParam}`, { method: 'GET', mode: 'cors' });
                        if (response.ok) {
                            resJson = await response.json();
                        }
                    } catch (e) {
                        console.warn(`GET attempt for ${action} failed:`, e);
                    }

                    // Fallback to POST with action in URL
                    if (!resJson || resJson.status === 'error' || resJson.error) {
                        const postBody = JSON.stringify({ 
                            action, 
                            type: action, 
                            id: 'PERM-CONFIG',
                            ID: 'PERM-CONFIG',
                            id_permiso: 'PERM-CONFIG',
                            ID_PERMISO: 'PERM-CONFIG',
                            cedula: 'PERM-CONFIG',
                            CEDULA: 'PERM-CONFIG',
                            data 
                        });
                        try {
                            const response = await fetch(targetUrl, {
                                method: 'POST',
                                headers: { 'Content-Type': 'text/plain' },
                                body: postBody
                            });
                            if (response.ok) {
                                try {
                                    resJson = await response.json();
                                } catch (_) {
                                    resJson = { status: 'success' };
                                }
                            } else {
                                await fetch(targetUrl, {
                                    method: 'POST',
                                    mode: 'no-cors',
                                    headers: { 'Content-Type': 'text/plain' },
                                    body: postBody
                                });
                                resJson = { status: 'success' };
                            }
                        } catch (postErr) {
                            await fetch(targetUrl, {
                                method: 'POST',
                                mode: 'no-cors',
                                headers: { 'Content-Type': 'text/plain' },
                                body: postBody
                            });
                            resJson = { status: 'success' };
                        }
                    }

                    if (resJson && (resJson.status === 'success' || resJson.result === 'success' || !resJson.error)) {
                        await fetchData(false);
                        if (successMsg) showToast(successMsg, "success");
                        return true;
                    } else {
                        throw new Error(resJson?.message || resJson?.error || "Error al procesar solicitud");
                    }
                } catch (error) {
                    console.error(`API Error (${action}):`, error);
                    showToast(`Aviso: ${error.message || 'Error al conectar con el servidor.'}`, "error");
                    return false;
                } finally {
                    setLoading(false);
                }
            };

            const loadDistribuidorPrices = async () => {
                setPreciosModal({ show: true, loading: true });
                try {
                    const separator = SCRIPT_URL.includes('?') ? '&' : '?';
                    const response = await fetch(`${SCRIPT_URL}${separator}action=getPrecios`, { method: 'GET', mode: 'cors' });
                    if(response.ok){
                        const data = await response.json();
                        if(!data.error) {
                            setDistribuidorPrices(data.data ? data.data : (Array.isArray(data) ? data : []));
                        }
                    }
                } catch (e) {
                    showToast("Error cargando precios.", "error");
                } finally {
                    setPreciosModal(prev => ({ ...prev, loading: false }));
                }
            };

            const NavItem = ({ id, icon, label, onClick, hidden = false }) => {
                if (hidden) return null;
                const isActive = activeView === id;
                return (
                    <button 
                        onClick={() => onClick ? onClick() : setActiveView(id)} 
                        className={`group relative flex items-center shrink-0 transition-all duration-200 overflow-hidden
                            ${isActive ? 'bg-[#2C4C8C] text-white shadow-md' : 'text-slate-500 hover:bg-slate-200 hover:text-slate-800'}
                            ${isSidebarCollapsed ? 'justify-center w-12 h-12 rounded-2xl mx-auto' : 'justify-start w-full px-4 py-3.5 rounded-xl'}`}
                        title={isSidebarCollapsed ? label : ''}
                    >
                        <Icon name={icon} size={isSidebarCollapsed ? 20 : 18} className={`shrink-0 transition-transform duration-200 ${isActive && isSidebarCollapsed ? 'scale-110' : ''} ${!isActive && 'group-hover:scale-110'}`} />
                        <span className={`whitespace-nowrap transition-all duration-300 font-black text-xs uppercase tracking-widest ${isSidebarCollapsed ? 'opacity-0 w-0 ml-0 hidden' : 'opacity-100 w-auto ml-3'}`}>
                            {label}
                        </span>
                    </button>
                );
            };

            if (initialLoading && currentUser) {
                return <div className="h-screen w-screen flex flex-col items-center justify-center bg-gradient-to-br from-[#1e3a6d] to-[#2C4C8C]"><Icon name="RefreshCw" size={48} className="text-white animate-spin mb-4" /><p className="text-white font-bold tracking-widest uppercase text-sm">Cargando Plataforma...</p></div>;
            }

            if (!currentUser) {
                return (
                    <div className="h-screen w-screen flex items-center justify-center p-4 bg-gradient-to-br from-[#1e3a6d] to-[#2C4C8C]">
                        <Toast show={toast.show} message={toast.message} type={toast.type} onClose={() => setToast({ ...toast, show: false })} />
                        <LoginView onLogin={handleLogin} loginLoading={loginLoading} />
                    </div>
                );
            }

            return (
                <div className="h-screen w-screen flex flex-col md:flex-row bg-white relative overflow-hidden animate-fade-in">
                    <Toast show={toast.show} message={toast.message} type={toast.type} onClose={() => setToast({ ...toast, show: false })} />
                    
                    {loading && (
                        <div className="absolute top-4 right-6 z-50 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full shadow-sm flex items-center gap-2 text-xs font-bold text-[#2C4C8C]">
                            <Icon name="RefreshCw" size={14} className="animate-spin" /> Sincronizando...
                        </div>
                    )}

                    <div className="md:hidden bg-white border-b border-slate-200 px-5 py-4 flex justify-between items-center shrink-0 z-20">
                        <img src="/soluciones_logo.png" alt="Logo Multimarcas" className="object-contain rounded-md" style={{ height: "32px", width: "auto", maxWidth: "150px" }} />
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center font-bold text-sm">
                                {currentUser?.nombre_cliente?.charAt(0).toUpperCase()}
                            </div>
                        </div>
                    </div>

                    <div className={`bg-slate-50 border-r border-slate-200 flex flex-col shrink-0 transition-all duration-300 relative z-30
                        ${isSidebarCollapsed ? 'w-[80px]' : 'w-64'} 
                        hidden md:flex h-full`}
                    >
                        <button onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} className="absolute -right-3.5 top-8 bg-white border border-slate-200 rounded-full p-1.5 text-slate-400 hover:text-[#2C4C8C] shadow-md z-40 transition-transform hover:scale-110">
                            <Icon name={isSidebarCollapsed ? "ChevronRight" : "ChevronLeft"} size={16} />
                        </button>

                        <div className={`flex justify-center items-center h-20 shrink-0 border-b border-slate-200 bg-white transition-all duration-300 overflow-hidden ${isSidebarCollapsed ? 'px-2' : 'px-6'}`}>
                            <img src="/soluciones_logo.png" alt="Logo Multimarcas" className="object-contain rounded-md transition-all duration-300" style={{ height: isSidebarCollapsed ? "32px" : "40px", width: "auto", maxWidth: "180px" }} />
                        </div>

                        <div className={`border-b border-slate-200 bg-white flex flex-col items-center text-center transition-all duration-300 overflow-hidden ${isSidebarCollapsed ? 'h-0 py-0 opacity-0' : 'h-auto py-5 opacity-100 px-4'}`}>
                            <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center font-black text-xl mb-3 shadow-inner">{currentUser?.nombre_cliente?.charAt(0).toUpperCase()}</div>
                            <h3 className="text-sm font-black text-slate-800 line-clamp-2 w-full leading-tight" title={currentUser?.nombre_cliente}>{currentUser?.nombre_cliente}</h3>
                            {userPerms.hasPrivileges && !userPerms.isGlobalAdmin && (
                                <span className="bg-blue-50 text-blue-700 border border-blue-200 px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-widest mt-2 w-fit mx-auto truncate max-w-full">UN: {userPerms.un}</span>
                            )}
                        </div>

                        <div className="flex flex-col flex-1 overflow-y-auto custom-scrollbar p-3 space-y-1.5 mt-2 pb-20">
                            {!isSidebarCollapsed && <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-3 mb-1 mt-2">Módulos</p>}
                            <NavItem id="tablero" icon="BarChart2" label="Tablero Cartera" />
                            <NavItem id="consultapayjoy" icon="Search" label="Consulta PayJoy" />
                        </div>

                        <div className="p-3 border-t border-slate-200 bg-white shrink-0">
                            <button onClick={handleLogout} className={`flex items-center justify-center p-3 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors border border-transparent hover:border-rose-100 group ${isSidebarCollapsed ? 'w-12 h-12 mx-auto' : 'w-full gap-2 px-4'}`} title={isSidebarCollapsed ? "Cerrar Sesión" : ""}>
                                <Icon name="LogOut" size={isSidebarCollapsed ? 20 : 16} className={`${isSidebarCollapsed && 'group-hover:scale-110 transition-transform'}`} /> 
                                {!isSidebarCollapsed && <span className="text-xs font-black uppercase tracking-widest">Cerrar Sesión</span>}
                            </button>
                        </div>
                    </div>

                    <div className="md:hidden bg-white border-t border-slate-200 flex justify-around p-2 gap-2 shrink-0 z-20">
                        <button onClick={() => setActiveView('tablero')} className={"flex-1 min-w-[90px] flex flex-col items-center justify-center p-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all " + (activeView === 'tablero' ? "bg-[#2C4C8C] text-white shadow-md" : "text-slate-500 hover:bg-slate-100")}><Icon name="BarChart2" size={18} className="mb-1"/> Tablero</button>
                        <button onClick={() => setActiveView('consultapayjoy')} className={"flex-1 min-w-[90px] flex flex-col items-center justify-center p-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all " + (activeView === 'consultapayjoy' ? "bg-[#2C4C8C] text-white shadow-md" : "text-slate-500 hover:bg-slate-100")}><Icon name="Search" size={18} className="mb-1"/> PayJoy</button>
                        <button onClick={handleLogout} className="flex-1 min-w-[90px] flex flex-col items-center justify-center p-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all text-rose-500 hover:bg-rose-50"><Icon name="LogOut" size={18} className="mb-1"/> Salir</button>
                    </div>

                    <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50/50 relative">
                        {db.notificacion && db.notificacion.activo && db.notificacion.mensaje && (activeView === 'tablero' || activeView === 'consultapayjoy') && (
                            <div className={`px-6 py-4 border-b flex items-start gap-3 ${db.notificacion.tipo === 'urgente' ? 'bg-rose-50 border-rose-200 text-rose-800' : 'bg-blue-50 border-blue-200 text-blue-800'} shrink-0 z-10`}>
                                <Icon name="AlertTriangle" size={20} className="shrink-0 mt-0.5" />
                                <div>
                                    <strong className="text-xs uppercase tracking-widest block mb-0.5">Aviso Importante</strong>
                                    <p className="text-sm font-semibold leading-relaxed">{db.notificacion.mensaje}</p>
                                </div>
                            </div>
                        )}

                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8 relative">
                            {activeView === 'consultapayjoy' ? (
                                <ConsultaPayJoyView />
                            ) : (
                                <TableroView showToast={showToast} currentUser={currentUser} userPerms={userPerms} setActiveView={setActiveView} />
                            )}
                        </div>
                    </div>

                    {preciosModal.show && (
                        <div className="fixed inset-0 z-[7000] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm px-4 animate-in fade-in">
                            <div className="bg-white rounded-3xl shadow-2xl max-w-5xl w-full max-h-[90vh] flex flex-col animate-pop-in border border-slate-200">
                                <div className="bg-amber-400 p-6 flex justify-between items-center shrink-0">
                                    <h3 className="text-amber-900 font-black text-xl tracking-tight">Lista de Precios - Mayorista</h3>
                                    <button onClick={() => setPreciosModal({show: false, loading: false})} className="text-amber-900 hover:bg-white/30 p-2 rounded-full transition-colors"><Icon name="X" size={24}/></button>
                                </div>
                                <div className="p-6 flex-1 overflow-y-auto custom-scrollbar bg-slate-50">
                                    {preciosModal.loading ? (
                                        <div className="flex flex-col items-center justify-center py-24 text-amber-600">
                                            <Icon name="RefreshCw" size={48} className="animate-spin mb-4" />
                                            <p className="font-bold text-lg">Consultando el servidor...</p>
                                        </div>
                                    ) : (
                                        <div className="rounded-2xl border border-slate-200 overflow-hidden bg-white shadow-sm">
                                            <table className="w-full text-sm text-left">
                                                <thead className="text-[10px] uppercase tracking-widest text-slate-500 bg-slate-50 sticky top-0 shadow-sm border-b border-slate-200">
                                                    <tr>
                                                        <th className="p-4 font-black">Marca</th>
                                                        <th className="p-4 font-black">Referencia</th>
                                                        <th className="p-4 font-black text-right">Costo Neto</th>
                                                        <th className="p-4 font-black text-right">Venta Público</th>
                                                        <th className="p-4 font-black text-right text-teal-600">Inicial Plataforma</th>
                                                        <th className="p-4 font-black text-right text-orange-600">Recibe Tienda</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-slate-100">
                                                    {distribuidorPrices.length > 0 ? distribuidorPrices.map((item, i) => {
                                                        const cost = parsePrice(item.cost);
                                                        const sale = parsePrice(item.sale);
                                                        const initial = parsePrice(item.initial);
                                                        const receive = parsePrice(item.receive) > 0 ? parsePrice(item.receive) : Math.round((sale * 0.20) / 1000) * 1000;
                                                        
                                                        return (
                                                            <tr key={i} className="hover:bg-slate-50 transition-colors">
                                                                <td className="p-4 font-black text-[#67B74D]">{item.brand}</td>
                                                                <td className="p-4 font-bold text-slate-700">{item.ref}</td>
                                                                <td className="p-4 text-right text-slate-500 font-medium">{formatCurrency(cost)}</td>
                                                                <td className="p-4 text-right font-black text-slate-800">{formatCurrency(sale)}</td>
                                                                <td className="p-4 text-right font-black text-teal-600 bg-teal-50/30">{formatCurrency(initial)}</td>
                                                                <td className="p-4 text-right font-black text-orange-600 bg-orange-50/30">{formatCurrency(receive)}</td>
                                                            </tr>
                                                        )
                                                    }) : <tr><td colSpan="6" className="p-12 text-center text-slate-400 font-medium">No hay precios disponibles en la base de datos.</td></tr>}
                                                </tbody>
                                            </table>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {qrModal.show && (
                        <div className="fixed inset-0 z-[8000] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm px-4 animate-in fade-in">
                            <div className="bg-white rounded-3xl shadow-2xl max-w-sm w-full overflow-hidden animate-pop-in text-center border border-slate-200">
                                <div className="bg-[#2C4C8C] p-5 flex justify-between items-center">
                                    <h3 className="text-white font-black text-lg tracking-tight">{qrModal.title}</h3>
                                    <button onClick={() => setQrModal({show: false, url: '', title: ''})} className="text-white/80 hover:bg-white/20 p-1.5 rounded-full transition-colors"><Icon name="X" size={20}/></button>
                                </div>
                                <div className="p-8 flex flex-col items-center bg-slate-50">
                                    <p className="text-xs font-bold text-slate-500 mb-6 uppercase tracking-widest text-center">Escanea para abrir el portal<br/>directo en tu celular</p>
                                    <div className="p-4 bg-white border border-slate-200 rounded-2xl shadow-sm inline-block">
                                        <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(qrModal.url)}`} alt="QR Code" className="w-52 h-52" />
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}

                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
    